{
  "name": "Nusuk Automation Pro Dashboard",
  "description": "A high-end administrative dashboard for managing visa data extraction from PDFs, email alias generation, and tracking registration status for the Nusuk/Eatmarna platform."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum RegistrationStatus {
  PENDING = 'PENDING',
  PROCESSING = 'PROCESSING',
  SUCCESS = 'SUCCESS',
  FAILED = 'FAILED',
  DUPLICATE = 'DUPLICATE'
}

export interface VisaRecord {
  id: string;
  passportNumber: string;
  visaNumber: string;
  fullName: string;
  nationality: string;
  email: string;
  status: RegistrationStatus;
  otpReceived: boolean;
  errorMessage?: string;
  registrationDate?: string;
}

export interface ExtractionResult {
  passportNumber: string;
  visaNumber: string;
  fullName: string;
  nationality: string;
}

export const PRIMARY_EMAIL = 'pharmacydr127@gmail.com';
export const UNIFIED_PASSWORD = 'Alaa@1111';
export const DEFAULT_MODEL = 'gemini-3-pro-preview';

import { GoogleGenAI, Type } from "@google/genai";
import { DEFAULT_MODEL } from "../constants";
import { ExtractionResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const extractVisaData = async (base64Pdf: string): Promise<ExtractionResult[]> => {
  try {
    const response = await ai.models.generateContent({
      model: DEFAULT_MODEL,
      contents: [
        {
          parts: [
            {
              inlineData: {
                mimeType: "application/pdf",
                data: base64Pdf
              }
            },
            {
              text: "Extract all visa information from this document. Return a JSON array of objects with the following keys: passportNumber, visaNumber, fullName (in English), nationality."
            }
          ]
        }
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              passportNumber: { type: Type.STRING },
              visaNumber: { type: Type.STRING },
              fullName: { type: Type.STRING },
              nationality: { type: Type.STRING },
            },
            required: ["passportNumber", "visaNumber", "fullName", "nationality"],
          }
        }
      }
    });

    const text = response.text || "[]";
    return JSON.parse(text);
  } catch (error) {
    console.error("Extraction error:", error);
    throw error;
  }
};

import React, { useState, useCallback } from 'react';
import { Layout, FileText, Settings, Activity, CheckCircle, XCircle, AlertCircle, Mail, Shield, Upload, Play, RefreshCw } from 'lucide-react';
import { VisaRecord, RegistrationStatus } from './types';
import { PRIMARY_EMAIL, UNIFIED_PASSWORD } from './constants';
import { extractVisaData } from './services/geminiService';

const App: React.FC = () => {
  const [records, setRecords] = useState<VisaRecord[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'queue' | 'settings'>('dashboard');

  const generateEmailAlias = (index: number) => {
    const [user, domain] = PRIMARY_EMAIL.split('@');
    return `${user}+v${Date.now()}${index}@${domain}`;
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    try {
      const reader = new FileReader();
      reader.onload = async (e) => {
        const base64 = (e.target?.result as string).split(',')[1];
        const extractedData = await extractVisaData(base64);

        const newRecords: VisaRecord[] = extractedData.map((data, idx) => ({
          id: Math.random().toString(36).substr(2, 9),
          ...data,
          email: generateEmailAlias(idx),
          status: RegistrationStatus.PENDING,
          otpReceived: false,
          registrationDate: new Date().toLocaleDateString('ar-SA')
        }));

        setRecords(prev => [...prev, ...newRecords]);
        setIsProcessing(false);
      };
      reader.readAsDataURL(file);
    } catch (error) {
      console.error(error);
      setIsProcessing(false);
      alert("حدث خطأ أثناء استخراج البيانات من الملف.");
    }
  };

  const startAutomation = async () => {
    if (records.length === 0) return;

    setIsProcessing(true);
    // Simulate the registration process
    const updatedRecords = [...records];

    for (let i = 0; i < updatedRecords.length; i++) {
      if (updatedRecords[i].status !== RegistrationStatus.PENDING) continue;

      updatedRecords[i].status = RegistrationStatus.PROCESSING;
      setRecords([...updatedRecords]);

      // Simulate delay for API calls and OTP reception
      await new Promise(resolve => setTimeout(resolve, 2000));

      // Simulated logic for Success/Failure/Duplicate
      const random = Math.random();
      if (random > 0.8) {
        updatedRecords[i].status = RegistrationStatus.FAILED;
        updatedRecords[i].errorMessage = "فشل في التحقق من OTP";
      } else if (random < 0.1) {
        updatedRecords[i].status = RegistrationStatus.DUPLICATE;
        updatedRecords[i].errorMessage = "التأشيرة مسجلة مسبقاً";
      } else {
        updatedRecords[i].status = RegistrationStatus.SUCCESS;
        updatedRecords[i].otpReceived = true;
      }

      setRecords([...updatedRecords]);
    }
    setIsProcessing(false);
  };

  const stats = {
    total: records.length,
    success: records.filter(r => r.status === RegistrationStatus.SUCCESS).length,
    failed: records.filter(r => r.status === RegistrationStatus.FAILED).length,
    duplicates: records.filter(r => r.status === RegistrationStatus.DUPLICATE).length,
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 pb-12">
      {/* Sidebar / Navigation */}
      <nav className="fixed top-0 left-0 right-0 h-16 bg-slate-900 border-b border-slate-800 flex items-center justify-between px-6 z-50">
        <div className="flex items-center gap-3">
          <div className="bg-emerald-500 p-2 rounded-lg">
            <Shield className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-xl font-bold tracking-tight">NUSUK <span className="text-emerald-500">PRO</span></h1>
        </div>

        <div className="flex items-center gap-6">
          <button 
            onClick={() => setActiveTab('dashboard')}
            className={`flex items-center gap-2 px-3 py-2 rounded-md transition ${activeTab === 'dashboard' ? 'bg-slate-800 text-emerald-400' : 'text-slate-400 hover:text-white'}`}
          >
            <Layout className="w-4 h-4" />
            <span>الرئيسية</span>
          </button>
          <button 
            onClick={() => setActiveTab('queue')}
            className={`flex items-center gap-2 px-3 py-2 rounded-md transition ${activeTab === 'queue' ? 'bg-slate-800 text-emerald-400' : 'text-slate-400 hover:text-white'}`}
          >
            <Activity className="w-4 h-4" />
            <span>قائمة التسجيل</span>
          </button>
          <button 
            onClick={() => setActiveTab('settings')}
            className={`flex items-center gap-2 px-3 py-2 rounded-md transition ${activeTab === 'settings' ? 'bg-slate-800 text-emerald-400' : 'text-slate-400 hover:text-white'}`}
          >
            <Settings className="w-4 h-4" />
            <span>الإعدادات</span>
          </button>
        </div>

        <div className="flex items-center gap-4">
          <div className="text-sm text-slate-400 text-left">
            <p className="font-semibold text-slate-200">{PRIMARY_EMAIL}</p>
            <p className="text-xs">المسؤول الرئيسي</p>
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="pt-24 px-8 max-w-7xl mx-auto">

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            {/* Header Section */}
            <div className="flex justify-between items-end">
              <div>
                <h2 className="text-3xl font-bold mb-2">نظام الأتمتة الذكي</h2>
                <p className="text-slate-400">تحويل ملفات التأشيرات إلى حسابات مفعلة تلقائياً عبر منصة نسك</p>
              </div>
              <div className="flex gap-3">
                <label className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 px-6 py-3 rounded-xl cursor-pointer transition border border-slate-700">
                  <Upload className="w-5 h-5 text-emerald-400" />
                  <span>رفع ملف PDF</span>
                  <input type="file" className="hidden" accept=".pdf" onChange={handleFileUpload} disabled={isProcessing} />
                </label>
                <button 
                  onClick={startAutomation}
                  disabled={isProcessing || records.length === 0}
                  className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-500 disabled:bg-slate-800 disabled:text-slate-500 px-8 py-3 rounded-xl font-bold transition shadow-lg shadow-emerald-900/20"
                >
                  {isProcessing ? <RefreshCw className="w-5 h-5 animate-spin" /> : <Play className="w-5 h-5" />}
                  <span>بدء التشغيل الآلي</span>
                </button>
              </div>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              {[
                { label: 'إجمالي التأشيرات', value: stats.total, icon: FileText, color: 'blue' },
                { label: 'تسجيلات ناجحة', value: stats.success, icon: CheckCircle, color: 'emerald' },
                { label: 'عمليات فشلت', value: stats.failed, icon: XCircle, color: 'red' },
                { label: 'مسجلة مسبقاً', value: stats.duplicates, icon: AlertCircle, color: 'amber' },
              ].map((stat, i) => (
                <div key={i} className="bg-slate-900 border border-slate-800 p-6 rounded-2xl">
                  <div className={`w-12 h-12 rounded-xl bg-${stat.color}-500/10 flex items-center justify-center mb-4`}>
                    <stat.icon className={`w-6 h-6 text-${stat.color}-400`} />
                  </div>
                  <p className="text-slate-400 text-sm mb-1">{stat.label}</p>
                  <p className="text-3xl font-bold">{stat.value}</p>
                </div>
              ))}
            </div>

            {/* Main Data Table View */}
            <div className="bg-slate-900 border border-slate-800 rounded-2xl overflow-hidden">
              <div className="p-6 border-b border-slate-800 flex justify-between items-center">
                <h3 className="font-bold text-lg">أحدث السجلات المستخرجة</h3>
                <span className="text-xs text-slate-500">تم استخراج {records.length} سجلات</span>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-right">
                  <thead>
                    <tr className="bg-slate-800/50 text-slate-400 text-sm">
                      <th className="px-6 py-4 font-semibold">الاسم الكامل</th>
                      <th className="px-6 py-4 font-semibold">رقم الجواز / التأشيرة</th>
                      <th className="px-6 py-4 font-semibold">البريد الإلكتروني المولّد</th>
                      <th className="px-6 py-4 font-semibold">الحالة</th>
                      <th className="px-6 py-4 font-semibold">الإجراء</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800">
                    {records.length === 0 ? (
                      <tr>
                        <td colSpan={5} className="px-6 py-20 text-center text-slate-500">
                          <div className="flex flex-col items-center gap-3">
                            <FileText className="w-12 h-12 opacity-20" />
                            <p>لا توجد بيانات حالية. قم برفع ملف PDF للبدء.</p>
                          </div>
                        </td>
                      </tr>
                    ) : (
                      records.map((record) => (
                        <tr key={record.id} className="hover:bg-slate-800/30 transition">
                          <td className="px-6 py-4">
                            <div className="font-semibold">{record.fullName}</div>
                            <div className="text-xs text-slate-500">{record.nationality}</div>
                          </td>
                          <td className="px-6 py-4">
                            <div className="text-sm font-mono text-slate-300">P: {record.passportNumber}</div>
                            <div className="text-sm font-mono text-emerald-500/80">V: {record.visaNumber}</div>
                          </td>
                          <td className="px-6 py-4 text-sm text-slate-400">
                            <div className="flex items-center gap-2">
                              <Mail className="w-3 h-3" />
                              {record.email}
                            </div>
                          </td>
                          <td className="px-6 py-4">
                            <StatusBadge status={record.status} />
                          </td>
                          <td className="px-6 py-4">
                             {record.errorMessage && <span className="text-xs text-red-400">{record.errorMessage}</span>}
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'settings' && (
          <div className="max-w-2xl bg-slate-900 border border-slate-800 rounded-2xl p-8 space-y-6">
            <h2 className="text-2xl font-bold mb-4">إعدادات النظام</h2>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-400 mb-2">البريد الإلكتروني الأساسي</label>
                <input 
                  type="email" 
                  readOnly 
                  value={PRIMARY_EMAIL} 
                  className="w-full bg-slate-950 border border-slate-700 rounded-xl px-4 py-3 text-slate-300 cursor-not-allowed"
                />
                <p className="text-xs text-slate-500 mt-2">سيتم استخدام هذا البريد لإنشاء نسخ (Alias) لاستقبال رموز التفعيل.</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-400 mb-2">كلمة المرور الموحدة</label>
                <div className="relative">
                  <input 
                    type="password" 
                    readOnly 
                    value={UNIFIED_PASSWORD} 
                    className="w-full bg-slate-950 border border-slate-700 rounded-xl px-4 py-3 text-slate-300 cursor-not-allowed"
                  />
                  <Shield className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-600" />
                </div>
              </div>

              <div className="pt-4 border-t border-slate-800">
                 <h4 className="font-semibold mb-3">وضع التشغيل الآلي</h4>
                 <div className="grid grid-cols-2 gap-4">
                    <button className="bg-emerald-500/10 border border-emerald-500/30 p-4 rounded-xl text-emerald-400 text-sm font-bold flex items-center justify-between">
                       <span>تفعيل الذكاء الاصطناعي</span>
                       <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                    </button>
                    <button className="bg-slate-800 border border-slate-700 p-4 rounded-xl text-slate-400 text-sm font-bold">
                       <span>تجاوز الكابتشا تلقائياً</span>
                    </button>
                 </div>
              </div>
            </div>
          </div>
        )}

      </main>

      {/* Floating Processing Indicator */}
      {isProcessing && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900 border border-emerald-500/50 px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 z-50">
          <div className="w-2 h-2 bg-emerald-500 rounded-full animate-ping"></div>
          <span className="text-sm font-bold text-emerald-400">جاري المعالجة والربط الذكي...</span>
        </div>
      )}
    </div>
  );
};

const StatusBadge: React.FC<{ status: RegistrationStatus }> = ({ status }) => {
  const configs = {
    [RegistrationStatus.PENDING]: { text: 'في الانتظار', classes: 'bg-slate-500/10 text-slate-500 border-slate-500/20' },
    [RegistrationStatus.PROCESSING]: { text: 'جاري التسجيل', classes: 'bg-blue-500/10 text-blue-400 border-blue-500/20 animate-pulse' },
    [RegistrationStatus.SUCCESS]: { text: 'تم التفعيل', classes: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' },
    [RegistrationStatus.FAILED]: { text: 'فشل العملية', classes: 'bg-red-500/10 text-red-400 border-red-500/20' },
    [RegistrationStatus.DUPLICATE]: { text: 'مسجل مسبقاً', classes: 'bg-amber-500/10 text-amber-400 border-amber-500/20' },
  };

  const config = configs[status];

  return (
    <span className={`px-3 py-1 rounded-full text-xs font-bold border ${config.classes}`}>
      {config.text}
    </span>
  );
};

export default App;

export enum RegistrationStatus {
  IDLE = 'IDLE',
  STARTING = 'STARTING',
  EXTRACTING_DATA = 'EXTRACTING_DATA',
  FILLING_FORM = 'FILLING_FORM',
  SOLVING_CAPTCHA = 'SOLVING_CAPTCHA',
  AWAITING_OTP = 'AWAITING_OTP',
  SUBMITTING = 'SUBMITTING',
  SUCCESS = 'SUCCESS',
  FAILED = 'FAILED',
  DUPLICATE = 'DUPLICATE'
}

export interface VisaRecord {
  id: string;
  passportNumber: string;
  visaNumber: string;
  fullName: string;
  nationality: string;
  dateOfBirth?: string;
  passportExpiry?: string;
  email: string;
  status: RegistrationStatus;
  otpCode?: string;
  logs: string[];
  errorMessage?: string;
}

export interface ExtractionResult {
  passportNumber: string;
  visaNumber: string;
  fullName: string;
  nationality: string;
  dateOfBirth: string;
  passportExpiry: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { DEFAULT_MODEL } from "../constants";
import { ExtractionResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const extractVisaData = async (base64Pdf: string): Promise<ExtractionResult[]> => {
  try {
    const response = await ai.models.generateContent({
      model: DEFAULT_MODEL,
      contents: [
        {
          parts: [
            {
              inlineData: {
                mimeType: "application/pdf",
                data: base64Pdf
              }
            },
            {
              text: "Extract ALL visa details required for Nusuk registration. I need: passportNumber, visaNumber, fullName, nationality, dateOfBirth (YYYY-MM-DD), and passportExpiry (YYYY-MM-DD). Return as JSON array."
            }
          ]
        }
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              passportNumber: { type: Type.STRING },
              visaNumber: { type: Type.STRING },
              fullName: { type: Type.STRING },
              nationality: { type: Type.STRING },
              dateOfBirth: { type: Type.STRING },
              passportExpiry: { type: Type.STRING },
            },
            required: ["passportNumber", "visaNumber", "fullName", "nationality", "dateOfBirth", "passportExpiry"],
          }
        }
      }
    });

    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Extraction error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  Layout, FileText, Settings, Activity, CheckCircle, 
  XCircle, AlertCircle, Mail, Shield, Upload, 
  Play, RefreshCw, Terminal, Key, Database, ChevronRight 
} from 'lucide-react';
import { VisaRecord, RegistrationStatus } from './types';
import { PRIMARY_EMAIL, UNIFIED_PASSWORD } from './constants';
import { extractVisaData } from './services/geminiService';

const App: React.FC = () => {
  const [records, setRecords] = useState<VisaRecord[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'logs' | 'settings'>('dashboard');
  const [selectedRecordForOtp, setSelectedRecordForOtp] = useState<string | null>(null);
  const [otpInput, setOtpInput] = useState('');

  const addLog = (id: string, message: string) => {
    setRecords(prev => prev.map(r => r.id === id ? { ...r, logs: [...r.logs, `[${new Date().toLocaleTimeString()}] ${message}`] } : r));
  };

  const updateStatus = (id: string, status: RegistrationStatus, error?: string) => {
    setRecords(prev => prev.map(r => r.id === id ? { ...r, status, errorMessage: error || r.errorMessage } : r));
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    try {
      const reader = new FileReader();
      reader.onload = async (e) => {
        const base64 = (e.target?.result as string).split(',')[1];
        const extractedData = await extractVisaData(base64);

        const newRecords: VisaRecord[] = extractedData.map((data, idx) => ({
          id: Math.random().toString(36).substr(2, 9),
          ...data,
          email: `${PRIMARY_EMAIL.split('@')[0]}+v${Date.now()}${idx}@${PRIMARY_EMAIL.split('@')[1]}`,
          status: RegistrationStatus.IDLE,
          logs: ['تم استخراج البيانات بنجاح من الملف'],
        }));

        setRecords(prev => [...prev, ...newRecords]);
        setIsProcessing(false);
      };
      reader.readAsDataURL(file);
    } catch (error) {
      setIsProcessing(false);
      alert("خطأ في قراءة الملف.");
    }
  };

  const runAutomationTask = async (record: VisaRecord) => {
    const id = record.id;

    // المرحلة 1: التشغيل
    updateStatus(id, RegistrationStatus.STARTING);
    addLog(id, "بدء تشغيل محرك الأتمتة (Browser Instance)");
    await new Promise(r => setTimeout(r, 1500));

    // المرحلة 2: التوجه للموقع
    addLog(id, "التوجه لرابط التسجيل في منصة نسك...");
    updateStatus(id, RegistrationStatus.FILLING_FORM);
    await new Promise(r => setTimeout(r, 2000));
    addLog(id, `تعبئة بيانات التأشيرة: ${record.visaNumber}`);
    addLog(id, `تعبئة بيانات الجواز: ${record.passportNumber}`);

    // المرحلة 3: الكابتشا
    updateStatus(id, RegistrationStatus.SOLVING_CAPTCHA);
    addLog(id, "جاري معالجة نظام الحماية (hCaptcha/reCAPTCHA)...");
    await new Promise(r => setTimeout(r, 3000));
    addLog(id, "تم تجاوز نظام الحماية بنجاح.");

    // المرحلة 4: طلب الـ OTP
    updateStatus(id, RegistrationStatus.AWAITING_OTP);
    addLog(id, `جاري إرسال رمز التحقق إلى: ${record.email}`);
    setSelectedRecordForOtp(id);
  };

  const submitOtp = () => {
    if (!selectedRecordForOtp || !otpInput) return;
    const id = selectedRecordForOtp;

    addLog(id, `تم استلام رمز التحقق: ${otpInput}`);
    updateStatus(id, RegistrationStatus.SUBMITTING);

    setTimeout(() => {
      addLog(id, "تم تأكيد الحساب بنجاح في قاعدة بيانات نسك.");
      updateStatus(id, RegistrationStatus.SUCCESS);
      setSelectedRecordForOtp(null);
      setOtpInput('');
    }, 2000);
  };

  const startAll = async () => {
    setIsProcessing(true);
    for (const record of records) {
      if (record.status === RegistrationStatus.IDLE) {
        await runAutomationTask(record);
        // ننتظر حتى ينتهي الـ OTP لهذا السجل قبل الانتقال للتالي (أو يمكن تشغيلهم بالتوازي)
        break; 
      }
    }
    setIsProcessing(false);
  };

  return (
