  >
    {icon}
    <span>{label}</span>
  </button>
);

const StatusChip: React.FC<{ status: RegistrationStatus }> = ({ status }) => {
  const map = {
    [RegistrationStatus.IDLE]: { text: 'جاهز', color: 'slate' },
    [RegistrationStatus.STARTING]: { text: 'بدء...', color: 'blue' },
    [RegistrationStatus.EXTRACTING_DATA]: { text: 'تحليل البيانات', color: 'indigo' },
    [RegistrationStatus.FILLING_FORM]: { text: 'تعبئة النموذج', color: 'blue' },
    [RegistrationStatus.SOLVING_CAPTCHA]: { text: 'فك الحماية', color: 'purple' },
    [RegistrationStatus.AWAITING_OTP]: { text: 'بانتظار OTP', color: 'amber' },
    [RegistrationStatus.SUBMITTING]: { text: 'إرسال نهائي', color: 'emerald' },
    [RegistrationStatus.SUCCESS]: { text: 'مكتمل', color: 'emerald' },
    [RegistrationStatus.FAILED]: { text: 'فشل', color: 'red' },
    [RegistrationStatus.DUPLICATE]: { text: 'مكرر', color: 'red' },
  };

  const { text, color } = map[status];
  return (
    <span className={`inline-flex items-center px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider border bg-${color}-500/10 text-${color}-400 border-${color}-500/20`}>
      {text}
    </span>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Layout, FileText, Settings, Activity, CheckCircle, 
  XCircle, AlertCircle, Mail, Shield, Upload, 
  Play, RefreshCw, Terminal, Key, Database, Server, Wifi, WifiOff 
} from 'lucide-react';
import { VisaRecord, RegistrationStatus } from './types';
import { PRIMARY_EMAIL, UNIFIED_PASSWORD } from './constants';
import { extractVisaData } from './services/geminiService';

const App: React.FC = () => {
  const [records, setRecords] = useState<VisaRecord[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'logs' | 'settings'>('dashboard');
  const [selectedRecordForOtp, setSelectedRecordForOtp] = useState<string | null>(null);
  const [otpInput, setOtpInput] = useState('');

  // إعدادات الخادم الوسيط (Runner)
  const [runnerUrl, setRunnerUrl] = useState('https://your-automation-server.com/api/register');
  const [runnerStatus, setRunnerStatus] = useState<'online' | 'offline'>('offline');

  // فحص اتصال الخادم الوسيط
  useEffect(() => {
    const checkRunner = async () => {
      try {
        const res = await fetch(runnerUrl.replace('/register', '/health'));
        setRunnerStatus(res.ok ? 'online' : 'offline');
      } catch {
        setRunnerStatus('offline');
      }
    };
    checkRunner();
    const interval = setInterval(checkRunner, 30000);
    return () => clearInterval(interval);
  }, [runnerUrl]);

  const addLog = (id: string, message: string) => {
    setRecords(prev => prev.map(r => r.id === id ? { ...r, logs: [...r.logs, `[${new Date().toLocaleTimeString()}] ${message}`] } : r));
  };

  const updateStatus = (id: string, status: RegistrationStatus, error?: string) => {
    setRecords(prev => prev.map(r => r.id === id ? { ...r, status, errorMessage: error || r.errorMessage } : r));
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    try {
      const reader = new FileReader();
      reader.onload = async (e) => {
        const base64 = (e.target?.result as string).split(',')[1];
        const extractedData = await extractVisaData(base64);

        const newRecords: VisaRecord[] = extractedData.map((data, idx) => ({
          id: Math.random().toString(36).substr(2, 9),
          ...data,
          email: `${PRIMARY_EMAIL.split('@')[0]}+v${Date.now()}${idx}@${PRIMARY_EMAIL.split('@')[1]}`,
          status: RegistrationStatus.IDLE,
          logs: ['تم استخراج البيانات وجاهز للإرسال الفعلي'],
        }));

        setRecords(prev => [...prev, ...newRecords]);
        setIsProcessing(false);
      };
      reader.readAsDataURL(file);
    } catch (error) {
      setIsProcessing(false);
      alert("خطأ في تحليل الملف.");
    }
  };

  const runAutomationTask = async (record: VisaRecord) => {
    const id = record.id;
    updateStatus(id, RegistrationStatus.STARTING);
    addLog(id, "جاري إرسال البيانات لخادم الأتمتة الفعلي...");

    try {
      // إرسال طلب حقيقي للخادم (يجب أن يكون لديك خادم Node.js/Python يتعامل مع Puppeteer)
      const response = await fetch(runnerUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          passportNumber: record.passportNumber,
          visaNumber: record.visaNumber,
          fullName: record.fullName,
          email: record.email,
          password: UNIFIED_PASSWORD,
          nationality: record.nationality,
          dateOfBirth: record.dateOfBirth,
          passportExpiry: record.passportExpiry
        })
      });

      if (!response.ok) throw new Error(`Server Error: ${response.status}`);

      const result = await response.json();

      if (result.step === 'AWAITING_OTP') {
        updateStatus(id, RegistrationStatus.AWAITING_OTP);
        addLog(id, "تم تعبئة البيانات بنجاح، بانتظار وصول كود التفعيل على إيميلك.");
        setSelectedRecordForOtp(id);
      } else {
        throw new Error(result.message || "خطأ غير معروف من الخادم");
      }

    } catch (error: any) {
      addLog(id, `فشل الاتصال: ${error.message}`);
      updateStatus(id, RegistrationStatus.FAILED, "تأكد من تشغيل خادم الأتمتة (Runner)");
    }
  };

  const submitOtp = async () => {
    if (!selectedRecordForOtp || !otpInput) return;
    const id = selectedRecordForOtp;
    const record = records.find(r => r.id === id);

    updateStatus(id, RegistrationStatus.SUBMITTING);
    addLog(id, `جاري إرسال كود التحقق ${otpInput} لإتمام التسجيل...`);

    try {
      const response = await fetch(`${runnerUrl}/verify`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, otp: otpInput })
      });

      if (response.ok) {
        addLog(id, "✅ تمت عملية التسجيل بنجاح وتم تفعيل الحساب.");
        updateStatus(id, RegistrationStatus.SUCCESS);
        setSelectedRecordForOtp(null);
        setOtpInput('');
      } else {
        throw new Error("كود التحقق غير صحيح أو انتهت صلاحيته");
      }
    } catch (error: any) {
      addLog(id, `❌ فشل التفعيل: ${error.message}`);
      updateStatus(id, RegistrationStatus.FAILED, error.message);
    }
  };

  return (
    <div className="min-h-screen bg-[#0a0f1c] text-slate-100 flex flex-col font-['Cairo']">
      {/* Navigation */}
      <nav className="h-20 bg-[#0f172a]/80 backdrop-blur-md border-b border-white/5 flex items-center justify-between px-10 sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-gradient-to-br from-emerald-400 to-emerald-600 p-2.5 rounded-2xl shadow-lg shadow-emerald-500/20">
            <Shield className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-black tracking-tighter leading-none">NUSUK <span className="text-emerald-500">PRO</span></h1>
            <p className="text-[10px] text-slate-500 font-bold tracking-[0.2em] mt-1 uppercase">Advanced Automation Suite</p>
          </div>
        </div>

        <div className="hidden md:flex bg-white/5 p-1.5 rounded-2xl border border-white/10">
          <TabButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={<Activity className="w-4 h-4"/>} label="العمليات" />
          <TabButton active={activeTab === 'logs'} onClick={() => setActiveTab('logs')} icon={<Terminal className="w-4 h-4"/>} label="السجل البرمجي" />
          <TabButton active={activeTab === 'settings'} onClick={() => setActiveTab('settings')} icon={<Settings className="w-4 h-4"/>} label="الإعدادات" />
        </div>

        <div className="flex items-center gap-6">
          <div className={`flex items-center gap-2 px-4 py-2 rounded-xl border ${runnerStatus === 'online' ? 'bg-emerald-500/5 border-emerald-500/20 text-emerald-400' : 'bg-red-500/5 border-red-500/20 text-red-400'}`}>
            {runnerStatus === 'online' ? <Wifi className="w-4 h-4" /> : <WifiOff className="w-4 h-4" />}
            <span className="text-xs font-bold uppercase">{runnerStatus === 'online' ? 'Runner Online' : 'Runner Offline'}</span>
          </div>
        </div>
      </nav>

      <main className="flex-1 p-10 max-w-7xl mx-auto w-full space-y-10">
        {activeTab === 'dashboard' && (
          <>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
              <div>
                <div className="inline-flex items-center gap-2 bg-emerald-500/10 text-emerald-400 px-3 py-1 rounded-full text-[10px] font-bold uppercase mb-3 border border-emerald-500/20">
                  <Server className="w-3 h-3" /> نظام الربط المباشر مفعل
                </div>
                <h2 className="text-4xl font-black text-white leading-tight">وحدة التحكم في التسجيل</h2>
                <p className="text-slate-400 max-w-lg mt-2 text-lg">ارفع ملف التأشيرات وسيقوم النظام بالتواصل مع خادم الأتمتة لتنفيذ التسجيل وطلب الأكواد فعلياً.</p>
              </div>
              <div className="flex gap-4 w-full md:w-auto">
                <label className="flex-1 md:flex-none flex items-center justify-center gap-3 bg-white/5 hover:bg-white/10 border border-white/10 px-8 py-4 rounded-2xl cursor-pointer transition-all active:scale-95 shadow-2xl">
                  <Upload className="w-5 h-5 text-emerald-400" />
                  <span className="font-bold">استيراد التأشيرات</span>
                  <input type="file" className="hidden" accept=".pdf" onChange={handleFileUpload} />
                </label>
                <button 
                  onClick={() => records.filter(r => r.status === RegistrationStatus.IDLE).forEach(runAutomationTask)}
                  disabled={records.length === 0 || runnerStatus === 'offline'}
                  className="flex-1 md:flex-none bg-emerald-600 hover:bg-emerald-500 disabled:opacity-30 disabled:grayscale px-10 py-4 rounded-2xl font-black text-lg flex items-center justify-center gap-3 transition-all shadow-xl shadow-emerald-600/30 active:scale-95"
                >
                  <Play className="w-5 h-5 fill-current" />
                  بدء التسجيل الفعلي
                </button>
              </div>
            </div>

            {/* OTP Alert Section */}
            {selectedRecordForOtp && (
              <div className="bg-gradient-to-r from-emerald-600 to-emerald-800 p-1 rounded-3xl shadow-2xl shadow-emerald-900/40 animate-in zoom-in-95 duration-300">
                <div className="bg-[#0a0f1c] rounded-[22px] p-8 flex flex-col lg:flex-row items-center justify-between gap-8">
                  <div className="flex items-center gap-6">
                    <div className="bg-emerald-500 p-5 rounded-2xl shadow-lg rotate-3">
                      <Key className="w-8 h-8 text-white" />
                    </div>
                    <div>
                      <h4 className="text-2xl font-black text-white">تأكيد الحساب الآن</h4>
                      <p className="text-slate-400 font-medium">وصل كود التفعيل إلى: <span className="text-emerald-400 font-bold">{records.find(r => r.id === selectedRecordForOtp)?.email}</span></p>
                    </div>
                  </div>
                  <div className="flex gap-3 w-full lg:w-auto">
                    <input 
                      type="text" 
                      maxLength={6}
                      placeholder="------"
                      value={otpInput}
                      onChange={(e) => setOtpInput(e.target.value)}
                      className="flex-1 lg:w-48 bg-white/5 border-2 border-emerald-500/30 rounded-2xl px-6 py-4 text-center text-3xl font-black tracking-[0.5em] focus:outline-none focus:border-emerald-500 transition-all text-emerald-400 placeholder:text-slate-800"
                    />
                    <button 
                      onClick={submitOtp}
                      className="bg-emerald-500 text-[#0a0f1c] px-10 py-4 rounded-2xl font-black text-lg hover:bg-emerald-400 transition-all active:scale-95"
                    >
                      تفعيل الحساب
                    </button>
                  </div>
                </div>
              </div>
            )}

            <div className="grid grid-cols-1 xl:grid-cols-4 gap-10">
              {/* Records List */}
              <div className="xl:col-span-3 space-y-6">
                <div className="flex items-center justify-between px-2">
                  <h3 className="font-black text-xl text-slate-300 flex items-center gap-3">
                    <Database className="w-5 h-5 text-emerald-500" /> قائمة الانتظار
                  </h3>
                  <span className="text-xs font-bold text-slate-500 bg-white/5 px-3 py-1 rounded-full">{records.length} سجل</span>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {records.map(record => (
                    <div key={record.id} className="bg-white/[0.02] border border-white/5 p-6 rounded-[2rem] hover:bg-white/[0.04] transition-all group relative overflow-hidden">
                      <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                         <FileText className="w-12 h-12" />
                      </div>
                      <div className="flex justify-between items-start mb-6">
                        <div className={`w-14 h-14 rounded-2xl flex items-center justify-center border-2 transition-colors ${record.status === RegistrationStatus.SUCCESS ? 'border-emerald-500 bg-emerald-500/10' : 'border-white/10 bg-white/5'}`}>
                           {record.status === RegistrationStatus.SUCCESS ? <CheckCircle className="w-7 h-7 text-emerald-500" /> : <span className="text-lg font-black text-slate-400">#</span>}
                        </div>
                        <StatusChip status={record.status} />
                      </div>

                      <div className="space-y-4">
                        <div>
                          <h4 className="text-xl font-black text-white group-hover:text-emerald-400 transition-colors">{record.fullName}</h4>
                          <p className="text-sm font-bold text-slate-500 mt-1 uppercase tracking-wider">{record.nationality}</p>
                        </div>

