            args: ['--no-sandbox', '--disable-setuid-sandbox'] 
        });
        const page = await browser.newPage();

        // التوجه لموقع نسك (مثال)
        await page.goto('https://www.nusuk.sa/ar/sign-up', { waitUntil: 'networkidle2' });

        // هنا يتم تعبئة الحقول آلياً بناءً على الحقول الفعلية في موقع نسك
        // await page.type('#passport_no', data.passportNumber);
