        res.json({ success: true, message: 'تم فتح المتصفح وإرسال الطلب' });
    } catch (err) {
        console.error(err);
        res.status(500).json({ success: false, error: err.message });
    }
});

app.listen(3000, () => console.log('المحرك يعمل على المنفذ 3000'));`;

const App: React.FC = () => {
  const [records, setRecords] = useState<VisaRecord[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'logs' | 'settings'>('dashboard');
  const [selectedRecordForOtp, setSelectedRecordForOtp] = useState<string | null>(null);
  const [otpInput, setOtpInput] = useState('');
  const [showGuide, setShowGuide] = useState(false);
  const [runnerStatus, setRunnerStatus] = useState<'online' | 'offline'>('offline');
  const [runnerUrl] = useState('http://localhost:3000/api/register');

  useEffect(() => {
    const checkRunner = async () => {
      try {
        const res = await fetch('http://localhost:3000/health');
        setRunnerStatus(res.ok ? 'online' : 'offline');
      } catch {
        setRunnerStatus('offline');
      }
    };
    checkRunner();
    const interval = setInterval(checkRunner, 5000);
    return () => clearInterval(interval);
  }, []);

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    alert('تم نسخ الكود بنجاح!');
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    try {
      const reader = new FileReader();
      reader.onload = async (e) => {
        const base64 = (e.target?.result as string).split(',')[1];
        const extractedData = await extractVisaData(base64);
        const newRecords: VisaRecord[] = extractedData.map((data, idx) => ({
          id: Math.random().toString(36).substr(2, 9),
          ...data,
          email: `${PRIMARY_EMAIL.split('@')[0]}+v${Date.now()}${idx}@${PRIMARY_EMAIL.split('@')[1]}`,
          status: RegistrationStatus.IDLE,
          logs: ['تم استخراج البيانات وجاهز للربط'],
        }));
        setRecords(prev => [...prev, ...newRecords]);
      };
      reader.readAsDataURL(file);
    } catch (error) {
      alert("خطأ في تحليل الملف.");
    }
  };

  const runTask = async (record: VisaRecord) => {
    if (runnerStatus === 'offline') {
        setShowGuide(true);
        return;
    }
    try {
      setRecords(prev => prev.map(r => r.id === record.id ? { ...r, status: RegistrationStatus.STARTING, logs: [...r.logs, 'إرسال للمحرك...'] } : r));
      const response = await fetch(runnerUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(record)
      });
      const res = await response.json();
      if (res.success) {
        setRecords(prev => prev.map(r => r.id === record.id ? { ...r, status: RegistrationStatus.AWAITING_OTP, logs: [...r.logs, '✅ المتصفح يعمل الآن!'] } : r));
        setSelectedRecordForOtp(record.id);
      }
    } catch (e: any) {
        setRecords(prev => prev.map(r => r.id === record.id ? { ...r, status: RegistrationStatus.FAILED, logs: [...r.logs, `خطأ: ${e.message}`] } : r));
    }
  };

  return (
    <div className="min-h-screen bg-[#0a0f1c] text-slate-100 flex flex-col font-['Cairo']">
      <nav className="h-20 bg-[#0f172a]/80 backdrop-blur-md border-b border-white/5 flex items-center justify-between px-10 sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-xl"><Shield className="w-6 h-6 text-white" /></div>
          <h1 className="text-2xl font-black">NUSUK <span className="text-emerald-500">PRO</span></h1>
        </div>
        <div className="flex items-center gap-4">
          <button onClick={() => setShowGuide(true)} className="flex items-center gap-2 bg-blue-500/10 text-blue-400 px-4 py-2 rounded-xl border border-blue-500/20 font-bold hover:bg-blue-500/20 transition"><HelpCircle className="w-4 h-4" /> كيف أشغل النظام؟</button>
          <div className={`flex items-center gap-2 px-4 py-2 rounded-xl border ${runnerStatus === 'online' ? 'bg-emerald-500/5 text-emerald-400 border-emerald-500/20' : 'bg-red-500/5 text-red-400 border-red-500/20'}`}>
            <Wifi className="w-4 h-4" />
            <span className="text-xs font-bold uppercase">{runnerStatus === 'online' ? 'المحرك متصل' : 'المحرك غير متصل'}</span>
          </div>
        </div>
      </nav>

      <main className="flex-1 p-10 max-w-7xl mx-auto w-full space-y-8">
        {showGuide && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-950/95 backdrop-blur-md animate-in fade-in">
             <div className="bg-[#0f172a] border border-white/10 w-full max-w-5xl rounded-[2.5rem] shadow-3xl overflow-hidden flex flex-col max-h-[90vh]">
                <div className="p-8 border-b border-white/5 flex justify-between items-center">
                   <h3 className="text-2xl font-black text-white flex items-center gap-3"><HelpCircle className="text-blue-400" /> دليل تشغيل "المحرك" خطوة بخطوة</h3>
                   <button onClick={() => setShowGuide(false)} className="bg-white/5 p-2 rounded-full hover:bg-white/10 transition"><XCircle /></button>
                </div>

                <div className="p-8 overflow-y-auto space-y-12">
                   <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                      <GuideStep num="1" icon={<FolderOpen />} title="أنشئ مجلد" desc="أنشئ مجلد جديد على جهازك باسم nusuk." />
                      <GuideStep num="2" icon={<Terminal />} title="افتح Terminal" desc="افتح الـ Terminal داخل المجلد." />
                      <GuideStep num="3" icon={<MousePointer2 />} title="ثبّت المكتبات" desc="انسخ الأوامر أدناه وشغلها." />
                      <GuideStep num="4" icon={<Play />} title="شغل الكود" desc="انسخ الكود وشغله بـ node index.js." />
                   </div>

                   <div className="space-y-6">
                      <div className="space-y-3">
                         <div className="flex items-center justify-between">
                            <h4 className="font-black text-blue-400 flex items-center gap-2"><Code className="w-4 h-4"/> 1. أوامر التثبيت (في الـ Terminal)</h4>
                            <button onClick={() => copyToClipboard('npm init -y && npm install express cors puppeteer puppeteer-extra puppeteer-extra-plugin-stealth')} className="text-[10px] bg-white/5 px-3 py-1 rounded-lg hover:bg-white/10">نسخ الأوامر</button>
                         </div>
                         <div className="bg-black/50 p-4 rounded-xl font-mono text-emerald-400 text-sm border border-white/5">
                            npm init -y && npm install express cors puppeteer puppeteer-extra puppeteer-extra-plugin-stealth
                         </div>
                      </div>

                      <div className="space-y-3">
                         <div className="flex items-center justify-between">
                            <h4 className="font-black text-blue-400 flex items-center gap-2"><FileText className="w-4 h-4"/> 2. كود الملف (index.js)</h4>
                            <button onClick={() => copyToClipboard(RUNNER_CODE)} className="text-[10px] bg-white/5 px-3 py-1 rounded-lg hover:bg-white/10">نسخ الكود بالكامل</button>
                         </div>
                         <div className="bg-black/50 p-6 rounded-xl font-mono text-slate-400 text-xs border border-white/5 max-h-64 overflow-y-auto scrollbar-thin">
                            <pre>{RUNNER_CODE}</pre>
                         </div>
                      </div>
                   </div>

                   <div className="bg-emerald-500/10 border border-emerald-500/20 p-6 rounded-3xl text-center">
                      <p className="text-emerald-400 font-bold text-sm">بمجرد تشغيل البرنامج، ستجد علامة "المحرك متصل" في الأعلى خضراء، وحينها سيعمل النظام حقيقياً ويصلك البريد.</p>
                   </div>
                </div>
             </div>
          </div>
        )}

        <div className="flex flex-col md:flex-row justify-between items-end gap-6">
           <div>
              <h2 className="text-4xl font-black text-white">لوحة التحكم</h2>
              <p className="text-slate-400 mt-2">ارفع ملف التأشيرة لبدء الاستخراج والتشغيل الفعلي.</p>
           </div>
           <div className="flex gap-4">
              <label className="flex items-center gap-3 bg-white/5 border border-white/10 px-8 py-4 rounded-2xl cursor-pointer hover:bg-white/10 transition">
                <Upload className="w-5 h-5 text-emerald-400" />
                <span className="font-bold">رفع PDF</span>
                <input type="file" className="hidden" accept=".pdf" onChange={handleFileUpload} />
              </label>
              <button 
                onClick={() => records.filter(r => r.status === RegistrationStatus.IDLE).forEach(runTask)}
                className="bg-emerald-600 px-10 py-4 rounded-2xl font-black flex items-center gap-3 hover:bg-emerald-500 transition shadow-xl shadow-emerald-600/20"
              >
                <Play className="w-5 h-5" /> بدء التشغيل
              </button>
           </div>
        </div>

        {runnerStatus === 'offline' && records.length > 0 && (
          <div className="bg-red-500/10 border border-red-500/20 p-6 rounded-3xl flex justify-between items-center animate-pulse">
             <div className="flex items-center gap-4">
                <AlertCircle className="text-red-500 w-8 h-8" />
                <p className="text-red-400 font-bold">المحرك مغلق! لن يصل بريد التفعيل من نسك إلا إذا قمت بتشغيل البرنامج على جهازك.</p>
             </div>
             <button onClick={() => setShowGuide(true)} className="bg-red-500 text-white px-6 py-2 rounded-xl font-black text-sm">كيف أشغله؟</button>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
           <div className="lg:col-span-2 space-y-4">
              {records.map(record => (
                <div key={record.id} className="bg-white/5 border border-white/10 p-6 rounded-3xl flex items-center justify-between group">
                   <div className="flex items-center gap-6">
                      <div className="w-16 h-16 bg-white/5 rounded-2xl flex items-center justify-center font-black text-2xl text-slate-700">#</div>
                      <div>
                         <h4 className="text-xl font-black text-white">{record.fullName}</h4>
                         <p className="text-sm text-slate-500">{record.passportNumber} | {record.nationality}</p>
                      </div>
                   </div>
                   <div className="flex items-center gap-4">
                      <StatusBadge status={record.status} />
                      <button onClick={() => runTask(record)} className="p-3 bg-emerald-500/10 text-emerald-500 rounded-xl opacity-0 group-hover:opacity-100 transition"><Play className="w-4 h-4" /></button>
                   </div>
                </div>
              ))}
              {records.length === 0 && (
                <div className="py-20 text-center border-2 border-dashed border-white/5 rounded-[3rem]">
                   <p className="text-slate-600 font-bold">لا توجد بيانات.. ارفع ملف PDF أولاً</p>
                </div>
              )}
           </div>

           <div className="bg-black/20 rounded-[2.5rem] p-8 border border-white/5 h-[500px] flex flex-col">
              <h3 className="font-black mb-6 flex items-center gap-2"><Terminal className="w-4 h-4 text-emerald-500" /> مراقبة المحرك</h3>
              <div className="flex-1 overflow-y-auto space-y-3 font-mono text-[10px]">
                 {records.flatMap(r => r.logs).reverse().map((log, i) => (
                    <div key={i} className="text-slate-400 bg-white/5 p-3 rounded-lg border-r-2 border-emerald-500">{log}</div>
                 ))}
              </div>
           </div>
