import { GoogleGenAI, Type } from "@google/genai";
import { DEFAULT_MODEL } from "../constants";
import { ExtractionResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const extractVisaData = async (base64Pdf: string): Promise<ExtractionResult[]> => {
  try {
    const response = await ai.models.generateContent({
      model: DEFAULT_MODEL,
      contents: [
        {
          parts: [
            {
              inlineData: {
                mimeType: "application/pdf",
                data: base64Pdf
              }
            },
            {
              text: "Extract specifically these 4 fields from the visa PDF for each person: 1. fullName (الاسم الكامل), 2. passportNumber (رقم الجواز), 3. visaNumber (رقم التأشيرة), 4. dateOfBirth (تاريخ الميلاد). Return the data as a clean JSON array of objects. Format dates as YYYY-MM-DD."
            }
          ]
        }
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              passportNumber: { type: Type.STRING },
              visaNumber: { type: Type.STRING },
              fullName: { type: Type.STRING },
              nationality: { type: Type.STRING },
              dateOfBirth: { type: Type.STRING },
              passportExpiry: { type: Type.STRING },
            },
            required: ["passportNumber", "visaNumber", "fullName", "dateOfBirth"],
          }
        }
      }
    });

    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Extraction error:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { 
  FileText, Shield, Upload, Play, Terminal, HelpCircle, 
  Download, Table as TableIcon, Trash2, CheckCircle2, Loader2, AlertCircle, XCircle
} from 'lucide-react';
import { VisaRecord, RegistrationStatus } from './types';
import { PRIMARY_EMAIL } from './constants';
import { extractVisaData } from './services/geminiService';

const App: React.FC = () => {
  const [records, setRecords] = useState<VisaRecord[]>([]);
  const [isExtracting, setIsExtracting] = useState(false);
  const [showGuide, setShowGuide] = useState(false);
  const [runnerStatus, setRunnerStatus] = useState<'online' | 'offline'>('offline');

  useEffect(() => {
    const checkRunner = async () => {
      try {
        const res = await fetch('http://localhost:3000/health');
        setRunnerStatus(res.ok ? 'online' : 'offline');
      } catch {
        setRunnerStatus('offline');
      }
    };
    checkRunner();
    const interval = setInterval(checkRunner, 5000);
    return () => clearInterval(interval);
  }, []);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsExtracting(true);
    try {
      const reader = new FileReader();
      reader.onload = async (e) => {
        const base64 = (e.target?.result as string).split(',')[1];
        const extractedData = await extractVisaData(base64);

        const newRecords: VisaRecord[] = extractedData.map((data, idx) => ({
          id: Math.random().toString(36).substr(2, 9),
          ...data,
          email: `${PRIMARY_EMAIL.split('@')[0]}+v${Date.now()}${idx}@${PRIMARY_EMAIL.split('@')[1]}`,
          status: RegistrationStatus.SUCCESS,
          logs: ['تم استخراج البيانات بنجاح'],
        }));

        setRecords(prev => [...newRecords, ...prev]);
        setIsExtracting(false);
      };
      reader.readAsDataURL(file);
    } catch (error) {
      console.error(error);
      alert("خطأ في تحليل الملف. تأكد من جودة ملف الـ PDF.");
      setIsExtracting(false);
    }
  };

  const exportToExcel = () => {
    if (records.length === 0) return;

    // Create CSV content with BOM for Arabic support
    const headers = ["الاسم الكامل", "رقم الجواز", "رقم التأشيرة", "تاريخ الميلاد"];
    const rows = records.map(r => [
      `"${r.fullName}"`,
      `"${r.passportNumber}"`,
      `"${r.visaNumber}"`,
      `"${r.dateOfBirth}"`
    ]);

    const csvContent = "\uFEFF" + [headers.join(","), ...rows.map(e => e.join(","))].join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `visas_export_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const clearRecords = () => {
    if (confirm("هل أنت متأكد من مسح جميع البيانات؟")) {
      setRecords([]);
    }
  };

  return (
    <div className="min-h-screen bg-[#0a0f1c] text-slate-100 flex flex-col font-['Cairo']">
      {/* Navbar */}
      <nav className="h-20 bg-[#0f172a]/80 backdrop-blur-md border-b border-white/5 flex items-center justify-between px-10 sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-xl"><Shield className="w-6 h-6 text-white" /></div>
          <h1 className="text-2xl font-black tracking-tight">NUSUK <span className="text-emerald-500">EXTRACTOR</span></h1>
        </div>
        <div className="flex items-center gap-4">
          <button onClick={() => setShowGuide(true)} className="text-slate-400 hover:text-white transition p-2">
            <HelpCircle className="w-6 h-6" />
          </button>
          <div className={`flex items-center gap-2 px-4 py-2 rounded-xl border ${runnerStatus === 'online' ? 'bg-emerald-500/5 text-emerald-400 border-emerald-500/20' : 'bg-red-500/5 text-red-400 border-red-500/20'}`}>
            <div className={`w-2 h-2 rounded-full ${runnerStatus === 'online' ? 'bg-emerald-500 animate-pulse' : 'bg-red-500'}`} />
            <span className="text-[10px] font-bold uppercase tracking-wider">{runnerStatus === 'online' ? 'المحرك متصل' : 'المحرك غير متصل'}</span>
          </div>
        </div>
      </nav>

      <main className="flex-1 p-10 max-w-7xl mx-auto w-full space-y-8">
        {/* Header Actions */}
        <div className="bg-[#0f172a] border border-white/5 rounded-[2.5rem] p-8 flex flex-col md:flex-row items-center justify-between gap-6 shadow-2xl">
          <div className="space-y-2 text-center md:text-right">
            <h2 className="text-3xl font-black">أداة استخراج بيانات التأشيرات</h2>
            <p className="text-slate-400 text-sm">ارفع ملف PDF يحتوي على التأشيرات وسنقوم بتنظيمها لك في جدول إكسل.</p>
          </div>

          <div className="flex flex-wrap justify-center gap-4">
            <label className={`flex items-center gap-3 bg-emerald-600 hover:bg-emerald-500 px-8 py-4 rounded-2xl cursor-pointer transition shadow-xl shadow-emerald-600/20 ${isExtracting ? 'opacity-50 cursor-not-allowed' : ''}`}>
              {isExtracting ? <Loader2 className="w-5 h-5 animate-spin" /> : <Upload className="w-5 h-5" />}
              <span className="font-black text-lg">{isExtracting ? 'جاري الاستخراج...' : 'رفع ملف التأشيرات'}</span>
