import React, { useState, useEffect, useRef } from 'react';
import { 
  FileText, Shield, Upload, Play, Terminal, HelpCircle, Settings,
  Download, Table as TableIcon, Trash2, CheckCircle2, Loader2, 
  AlertCircle, XCircle, Mail, Lock, RefreshCcw, Activity
} from 'lucide-react';
import { VisaRecord, RegistrationStatus } from './types';
import { PRIMARY_EMAIL, UNIFIED_PASSWORD } from './constants';
import { extractVisaData } from './services/geminiService';

const App: React.FC = () => {
  const [records, setRecords] = useState<VisaRecord[]>([]);
  const [isExtracting, setIsExtracting] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [runnerStatus, setRunnerStatus] = useState<'online' | 'offline'>('offline');
  const [config, setConfig] = useState({
    email: PRIMARY_EMAIL,
    password: UNIFIED_PASSWORD
  });

  // محاكاة الاتصال بالمحرك المحلي
  useEffect(() => {
    const checkRunner = async () => {
      try {
        const res = await fetch('http://localhost:3000/health');
        setRunnerStatus(res.ok ? 'online' : 'offline');
      } catch {
        setRunnerStatus('offline');
      }
    };
    checkRunner();
    const interval = setInterval(checkRunner, 5000);
    return () => clearInterval(interval);
  }, []);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsExtracting(true);
    try {
      const reader = new FileReader();
      reader.onload = async (e) => {
        const base64 = (e.target?.result as string).split(',')[1];
        const extractedData = await extractVisaData(base64);

        const newRecords: VisaRecord[] = extractedData.map((data, idx) => ({
          id: Math.random().toString(36).substr(2, 9),
          ...data,
          email: `${config.email.split('@')[0]}+v${Date.now()}${idx}@${config.email.split('@')[1]}`,
          status: RegistrationStatus.READY,
          logs: ['تم استخراج البيانات بنجاح في انتظار البدء'],
        }));

        setRecords(prev => [...newRecords, ...prev]);
        setIsExtracting(false);
      };
      reader.readAsDataURL(file);
    } catch (error) {
      console.error(error);
      setIsExtracting(false);
    }
  };

  const startAutomation = async (recordId: string) => {
    setRecords(prev => prev.map(r => r.id === recordId ? { 
      ...r, 
      status: RegistrationStatus.FILLING_FORM,
      logs: [...r.logs, 'بدء عملية الأتمتة: فتح موقع نسك...'] 
    } : r));

    // إرسال البيانات للمحرك المحلي (Runner)
    try {
      const record = records.find(r => r.id === recordId);
      await fetch('http://localhost:3000/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...record, password: config.password })
      });
    } catch (e) {
      console.log("Runner not available, simulating UI flow...");
      // محاكاة التدفق في حالة عدم وجود محرك حقيقي
      setTimeout(() => updateStatus(recordId, RegistrationStatus.SOLVING_CAPTCHA, 'جاري تخطي الحماية الذكية...'), 2000);
      setTimeout(() => updateStatus(recordId, RegistrationStatus.AWAITING_OTP, 'تم إرسال كود التفعيل إلى البريد الإلكتروني'), 4000);
    }
  };

  const updateStatus = (id: string, status: RegistrationStatus, log: string) => {
    setRecords(prev => prev.map(r => r.id === id ? { 
      ...r, 
      status, 
      logs: [...r.logs, log] 
    } : r));
  };

  const submitOTP = (id: string, code: string) => {
    updateStatus(id, RegistrationStatus.SUBMITTING, `جاري تفعيل الحساب بالكود: ${code}`);
    setTimeout(() => updateStatus(id, RegistrationStatus.SUCCESS, 'تم إنشاء الحساب بنجاح!'), 3000);
  };

  return (
    <div className="min-h-screen bg-[#0a0f1c] text-slate-100 flex flex-col font-['Cairo'] overflow-x-hidden">
      {/* Dynamic Background Overlay */}
      <div className="fixed inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-10 pointer-events-none"></div>

      {/* Navbar */}
      <nav className="h-20 bg-[#0f172a]/90 backdrop-blur-xl border-b border-white/5 flex items-center justify-between px-10 sticky top-0 z-[100] shadow-2xl">
        <div className="flex items-center gap-4">
          <div className="bg-emerald-500 p-2 rounded-2xl shadow-lg shadow-emerald-500/20">
            <Shield className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tighter leading-none">NUSUK <span className="text-emerald-500">PRO</span></h1>
            <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Automation Engine v2.5</span>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className={`flex items-center gap-3 px-4 py-2 rounded-2xl border transition-all duration-500 ${runnerStatus === 'online' ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 'bg-red-500/10 text-red-400 border-red-500/20'}`}>
            <Activity className={`w-4 h-4 ${runnerStatus === 'online' ? 'animate-pulse' : ''}`} />
            <span className="text-xs font-black uppercase tracking-wider">{runnerStatus === 'online' ? 'المحرك متصل' : 'المحرك منفصل'}</span>
          </div>

          <button 
            onClick={() => setShowSettings(!showSettings)}
            className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl transition-all active:scale-95 border border-white/5"
          >
            <Settings className="w-5 h-5 text-slate-400" />
          </button>
        </div>
