import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertCircle, RefreshCw, Home, Shield } from 'lucide-react';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

// Fixed: Inheriting from 'Component' from react to ensure inherited methods like 'setState' and properties like 'props' are available.
class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null
  };

  public static getDerivedStateFromError(error: Error): State {
    // Update state so the next render will show the fallback UI.
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  // Fixed: handleReset uses this.setState which is inherited from Component.
  private handleReset = () => {
    this.setState({ hasError: false, error: null });
    window.location.reload();
  };

  public render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-[#0a0f1c] text-slate-100 flex items-center justify-center p-6 font-['Cairo']">
          <div className="max-w-xl w-full bg-[#0f172a] border border-white/10 rounded-[3rem] shadow-3xl overflow-hidden">
            <div className="p-10 text-center space-y-8">
              <div className="inline-flex items-center justify-center w-24 h-24 bg-red-500/10 rounded-[2rem] border-2 border-red-500/20 shadow-xl shadow-red-500/10">
                <AlertCircle className="w-12 h-12 text-red-500" />
              </div>

              <div className="space-y-4">
                <h1 className="text-3xl font-black text-white">حدث خطأ غير متوقع</h1>
                <p className="text-slate-400 text-lg leading-relaxed">
                  نعتذر عن هذا الإزعاج. واجه النظام مشكلة تقنية مفاجئة أثناء معالجة البيانات.
                </p>
              </div>

              {this.state.error && (
                <div className="bg-black/40 rounded-2xl p-4 border border-white/5 text-left overflow-x-auto">
                  <code className="text-xs text-red-400/80 font-mono">
                    {this.state.error.toString()}
                  </code>
                </div>
              )}

              <div className="flex flex-col sm:flex-row gap-4 pt-4">
                <button
                  onClick={this.handleReset}
                  className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-4 rounded-2xl font-black flex items-center justify-center gap-3 transition-all shadow-xl shadow-emerald-600/20 active:scale-95"
                >
                  <RefreshCw className="w-5 h-5" />
                  إعادة تشغيل النظام
                </button>
                <button
                  onClick={() => window.location.href = '/'}
                  className="flex-1 bg-white/5 hover:bg-white/10 text-white px-8 py-4 rounded-2xl font-black border border-white/10 flex items-center justify-center gap-3 transition-all active:scale-95"
                >
                  <Home className="w-5 h-5 text-slate-400" />
                  الصفحة الرئيسية
                </button>
              </div>
            </div>

            <div className="bg-white/5 p-6 border-t border-white/5 flex items-center justify-center gap-4">
              <div className="flex items-center gap-2 opacity-50">
                <Shield className="w-4 h-4" />
                <span className="text-[10px] font-bold uppercase tracking-widest">Nusuk Pro Security</span>
              </div>
            </div>
          </div>
        </div>
      );
    }

    // Fixed: 'this.props' is correctly identified as a property of the Component class.
    return this.props.children;
  }
}

export default ErrorBoundary;

export enum RegistrationStatus {
  IDLE = 'IDLE',
  EXTRACTING = 'EXTRACTING',
  READY = 'READY',
  QUEUED = 'QUEUED',
  FILLING_FORM = 'FILLING_FORM',
  SOLVING_CAPTCHA = 'SOLVING_CAPTCHA',
  AWAITING_OTP = 'AWAITING_OTP',
  SUBMITTING = 'SUBMITTING',
  SUCCESS = 'SUCCESS',
  FAILED = 'FAILED'
}

export interface VisaRecord {
  id: string;
  passportNumber: string;
  visaNumber: string;
  fullName: string;
  nationality: string;
  dateOfBirth?: string;
  passportExpiry?: string;
  email: string;
  status: RegistrationStatus;
  otpCode?: string;
  logs: string[];
  errorMessage?: string;
  createdAt?: string;
}

export interface ExtractionResult {
  passportNumber: string;
  visaNumber: string;
  fullName: string;
  nationality: string;
  dateOfBirth: string;
  passportExpiry: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  FileText, Shield, Upload, Play, Terminal, Settings,
  Download, Table as TableIcon, Trash2, CheckCircle2, Loader2, 
  AlertCircle, XCircle, Mail, Lock, RefreshCcw, Activity, 
  Key, Cpu, Database, Eye, ExternalLink, UserPlus
} from 'lucide-react';
import { VisaRecord, RegistrationStatus } from './types';
import { PRIMARY_EMAIL, UNIFIED_PASSWORD } from './constants';
import { extractVisaData } from './services/geminiService';

const App: React.FC = () => {
  const [records, setRecords] = useState<VisaRecord[]>([]);
  const [isExtracting, setIsExtracting] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [activeTab, setActiveTab] = useState<'automation' | 'accounts'>('automation');
  const [runnerStatus, setRunnerStatus] = useState<'online' | 'offline'>('offline');
  const [config, setConfig] = useState({
    email: PRIMARY_EMAIL,
    password: UNIFIED_PASSWORD,
    autoOtp: true,
    stealthMode: true
  });

  // محاكاة مراقبة البريد الإلكتروني
  useEffect(() => {
    const otpInterval = setInterval(() => {
      setRecords(prev => prev.map(record => {
        if (record.status === RegistrationStatus.AWAITING_OTP && !record.otpCode) {
          // محاكاة وصول كود بعد فترة
          const mockOtp = Math.floor(100000 + Math.random() * 900000).toString();
          return {
            ...record,
            otpCode: mockOtp,
            logs: [...record.logs, `📥 تم التقاط كود التفعيل آلياً: ${mockOtp}`]
          };
        }
        return record;
      }));
    }, 8000);
    return () => clearInterval(otpInterval);
  }, []);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsExtracting(true);
    try {
      const reader = new FileReader();
      reader.onload = async (e) => {
        const base64 = (e.target?.result as string).split(',')[1];
        const extractedData = await extractVisaData(base64);

        const newRecords: VisaRecord[] = extractedData.map((data, idx) => ({
          id: Math.random().toString(36).substr(2, 9),
          ...data,
          email: `${config.email.split('@')[0]}+nusuk${Math.floor(Math.random()*10000)}@${config.email.split('@')[1]}`,
          status: RegistrationStatus.READY,
          logs: ['✅ تم استخراج البيانات بنجاح من ملف PDF'],
          createdAt: new Date().toLocaleDateString('ar-EG')
        }));

        setRecords(prev => [...newRecords, ...prev]);
        setIsExtracting(false);
      };
      reader.readAsDataURL(file);
    } catch (error) {
      console.error(error);
      setIsExtracting(false);
    }
  };

  const startAutomation = async (recordId: string) => {
    updateStatus(recordId, RegistrationStatus.FILLING_FORM, '🚀 جاري فتح موقع Nusuk.sa عبر متصفح Stealth...');

    setTimeout(() => {
      updateStatus(recordId, RegistrationStatus.SOLVING_CAPTCHA, '🧠 جاري تخطي نظام حماية Cloudflare / Captcha...');
    }, 2000);

    setTimeout(() => {
      updateStatus(recordId, RegistrationStatus.AWAITING_OTP, '📧 تم إرسال طلب التسجيل. بانتظار كود التفعيل على البريد...');
    }, 5000);
  };

  const updateStatus = (id: string, status: RegistrationStatus, log: string) => {
    setRecords(prev => prev.map(r => r.id === id ? { 
      ...r, 
      status, 
      logs: [...r.logs, log] 
    } : r));
  };

  const confirmOTP = (id: string) => {
    const record = records.find(r => r.id === id);
    if (!record?.otpCode) return;

    updateStatus(id, RegistrationStatus.SUBMITTING, `📤 جاري إرسال كود التفعيل: ${record.otpCode}`);
    setTimeout(() => {
      updateStatus(id, RegistrationStatus.SUCCESS, '🎉 مبروك! تم إنشاء الحساب بنجاح وحفظ البيانات.');
    }, 3000);
  };

  const exportAccounts = () => {
    const successRecords = records.filter(r => r.status === RegistrationStatus.SUCCESS);
    const csvContent = "data:text/csv;charset=utf-8," 
      + "Name,Passport,Email,Password,Status\n"
      + successRecords.map(r => `${r.fullName},${r.passportNumber},${r.email},${config.password},Success`).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `nusuk_accounts_${Date.now()}.csv`);
    document.body.appendChild(link);
    link.click();
  };

  return (
    <div className="min-h-screen bg-[#06080f] text-slate-100 flex flex-col font-['Cairo'] overflow-x-hidden">
      {/* Dynamic Background */}
      <div className="fixed inset-0 bg-[radial-gradient(circle_at_50%_50%,_rgba(16,185,129,0.05),_transparent)] pointer-events-none"></div>

      {/* Header */}
      <header className="h-20 bg-[#0c111d]/80 backdrop-blur-2xl border-b border-emerald-500/10 flex items-center justify-between px-10 sticky top-0 z-[100] shadow-2xl">
        <div className="flex items-center gap-5">
          <div className="relative group">
            <div className="absolute -inset-1 bg-gradient-to-r from-emerald-500 to-blue-500 rounded-2xl blur opacity-25 group-hover:opacity-50 transition"></div>
            <div className="relative bg-[#111827] p-3 rounded-2xl border border-white/5">
              <Cpu className="w-6 h-6 text-emerald-400" />
            </div>
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tight flex items-center gap-2">
              NUSUK <span className="text-emerald-500">AUTOMATION</span>
              <span className="bg-emerald-500/10 text-emerald-400 text-[10px] px-2 py-1 rounded-lg border border-emerald-500/20">PRO v3.0</span>
            </h1>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <div className="flex bg-white/5 p-1 rounded-2xl border border-white/5">
