    [RegistrationStatus.SOLVING_CAPTCHA]: { label: 'تخطي الحماية', color: 'text-purple-400 bg-purple-500/10 border-purple-500/20', icon: Shield, pulse: true },
    [RegistrationStatus.AWAITING_OTP]: { label: 'انتظار OTP', color: 'text-amber-400 bg-amber-500/10 border-amber-500/20', icon: Mail },
    [RegistrationStatus.SUCCESS]: { label: 'مكتمل بنجاح', color: 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20', icon: CheckCircle2 },
    [RegistrationStatus.FAILED]: { label: 'فشل العملية', color: 'text-red-400 bg-red-500/10 border-red-500/20', icon: XCircle },
  };

  const current = map[status] || map[RegistrationStatus.READY];
