  return (
    <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-full border text-[10px] font-black uppercase tracking-widest ${current.color}`}>
      <Icon className={`w-3 h-3 ${current.pulse ? 'animate-spin' : ''}`} />
      {current.label}
    </div>
  );
};

