  visaNumber: string;
  fullName: string;
  nationality: string;
  dateOfBirth: string;
  passportExpiry: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { DEFAULT_MODEL } from "../constants";
import { ExtractionResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const extractVisaData = async (base64Pdf: string): Promise<ExtractionResult[]> => {
  try {
    const response = await ai.models.generateContent({
      model: DEFAULT_MODEL,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: "application/pdf",
              data: base64Pdf
            }
          },
          {
            text: `Extract data for Nusuk/Umrah registration. 
            RULES:
            1. Convert all Arabic names to Latin characters if possible.
            2. Dates MUST be YYYY-MM-DD.
            3. Passport numbers must be exactly as written (case-sensitive).
            4. If multiple visas exist in one PDF, return an array of all.

            Return JSON matching the schema precisely.`
          }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              passportNumber: { type: Type.STRING },
              visaNumber: { type: Type.STRING },
              fullName: { type: Type.STRING },
              dateOfBirth: { type: Type.STRING },
              nationality: { type: Type.STRING },
              passportExpiry: { type: Type.STRING }
            },
            required: ["passportNumber", "visaNumber", "fullName", "dateOfBirth"],
          }
        }
      }
    });

    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Gemini Extraction Error:", error);
    throw error;
  }
};

