import { PRIMARY_EMAIL, UNIFIED_PASSWORD } from './constants';
import { extractVisaData } from './services/geminiService';

const App: React.FC = () => {
  const [records, setRecords] = useState<VisaRecord[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [activeTab, setActiveTab] = useState<'monitor' | 'accounts'>('monitor');
  const [error, setError] = useState<string | null>(null);

  const [config, setConfig] = useState({
    email: PRIMARY_EMAIL,
    password: UNIFIED_PASSWORD,
    gateway: 'https://stealth-proxy.nusuk-api.com',
    threads: 3,
    solveCaptcha: true
  });

  const addLog = (id: string, message: string, type: 'info' | 'error' | 'success' | 'network' = 'info') => {
    const timestamp = new Date().toLocaleTimeString();
    setRecords(prev => prev.map(r => r.id === id ? {
      ...r,
      logs: [...r.logs, { timestamp, message, type }]
    } : r));
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    setError(null);

    try {
      const reader = new FileReader();

      reader.onerror = () => {
        setError("خطأ في قراءة ملف الـ PDF");
        setIsProcessing(false);
      };

      reader.onload = async (e) => {
        try {
          const base64 = (e.target?.result as string).split(',')[1];
          const data = await extractVisaData(base64);

          if (!data || data.length === 0) {
            throw new Error("لم يتم العثور على بيانات تأشيرات صالحة في الملف");
          }

          const newRecords: VisaRecord[] = data.map(v => ({
            id: Math.random().toString(36).substr(2, 9),
            ...v,
            email: `${config.email.split('@')[0]}+ns${Math.floor(Math.random()*10000)}@${config.email.split('@')[1]}`,
            status: RegistrationStatus.READY,
            createdAt: new Date().toISOString(),
            logs: [{ timestamp: new Date().toLocaleTimeString(), message: '✅ تم تحليل بيانات التأشيرة ومطابقتها برمجياً', type: 'success' }],
            automationConfig: {
              proxy: `res-proxy-${Math.floor(Math.random()*999)}.net:8080`,
              userAgent: "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36...",
              fingerprintId: `fp_${Math.random().toString(36).substr(2, 12)}`,
              resolution: "1920x1080"
            }
          }));

          setRecords(prev => [...newRecords, ...prev]);
        } catch (err: any) {
          console.error(err);
          setError(err.message || "فشل استخراج البيانات. تأكد من أن الملف PDF أصلي.");
        } finally {
          setIsProcessing(false);
          // Reset input value to allow re-uploading the same file
          if (event.target) event.target.value = '';
        }
      };

      reader.readAsDataURL(file);
    } catch (err) {
      console.error(err);
      setError("حدث خطأ غير متوقع");
      setIsProcessing(false);
    }
  };

  const executeRegistration = async (id: string) => {
    const record = records.find(r => r.id === id);
    if (!record) return;

    updateStatus(id, RegistrationStatus.HANDSHAKE);
    addLog(id, `🌐 الاتصال عبر البروكسي: ${record.automationConfig.proxy}`, 'network');
    addLog(id, `🔑 جلب Tokens و Session Cookies من Nusuk.sa...`, 'info');

    await new Promise(r => setTimeout(r, 2000));
    updateStatus(id, RegistrationStatus.FILLING_DATA);
    addLog(id, `📝 حقن البيانات لـ: ${record.fullName}`, 'info');

    await new Promise(r => setTimeout(r, 2000));
    updateStatus(id, RegistrationStatus.SOLVING_CAPTCHA);
    addLog(id, `🧠 جاري حل الكابتشا (v3) تلقائياً...`, 'info');

    await new Promise(r => setTimeout(r, 3000));
    updateStatus(id, RegistrationStatus.AWAITING_OTP);
    addLog(id, `📧 تم إرسال طلب التسجيل. المحرك الآن يراقب صندوق الوارد: ${record.email}`, 'network');
  };

