import React, { ErrorInfo, ReactNode } from 'react';
import { AlertCircle, RefreshCw, Home, Shield } from 'lucide-react';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

// Fixed: Using React.Component explicitly to ensure 'setState' and 'props' are correctly inherited and recognized by the TypeScript compiler.
class ErrorBoundary extends React.Component<Props, State> {
  // Added constructor to explicitly initialize state and call super(props)
  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      error: null
    };
  }

  public static getDerivedStateFromError(error: Error): State {
    // Update state so the next render will show the fallback UI.
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  // Fixed: 'this.setState' is available via inheritance from React.Component.
  private handleReset = () => {
    this.setState({ hasError: false, error: null });
    window.location.reload();
  };

  public render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-[#0a0f1c] text-slate-100 flex items-center justify-center p-6 font-['Cairo']">
          <div className="max-w-xl w-full bg-[#0f172a] border border-white/10 rounded-[3rem] shadow-3xl overflow-hidden">
            <div className="p-10 text-center space-y-8">
              <div className="inline-flex items-center justify-center w-24 h-24 bg-red-500/10 rounded-[2rem] border-2 border-red-500/20 shadow-xl shadow-red-500/10">
                <AlertCircle className="w-12 h-12 text-red-500" />
              </div>

              <div className="space-y-4">
                <h1 className="text-3xl font-black text-white">حدث خطأ غير متوقع</h1>
                <p className="text-slate-400 text-lg leading-relaxed">
                  نعتذر عن هذا الإزعاج. واجه النظام مشكلة تقنية مفاجئة أثناء معالجة البيانات.
                </p>
              </div>

              {this.state.error && (
                <div className="bg-black/40 rounded-2xl p-4 border border-white/5 text-left overflow-x-auto">
                  <code className="text-xs text-red-400/80 font-mono">
                    {this.state.error.toString()}
                  </code>
                </div>
              )}

              <div className="flex flex-col sm:flex-row gap-4 pt-4">
                <button
                  onClick={this.handleReset}
                  className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-4 rounded-2xl font-black flex items-center justify-center gap-3 transition-all shadow-xl shadow-emerald-600/20 active:scale-95"
                >
                  <RefreshCw className="w-5 h-5" />
                  إعادة تشغيل النظام
                </button>
                <button
                  onClick={() => window.location.href = '/'}
                  className="flex-1 bg-white/5 hover:bg-white/10 text-white px-8 py-4 rounded-2xl font-black border border-white/10 flex items-center justify-center gap-3 transition-all active:scale-95"
                >
                  <Home className="w-5 h-5 text-slate-400" />
                  الصفحة الرئيسية
                </button>
              </div>
            </div>

            <div className="bg-white/5 p-6 border-t border-white/5 flex items-center justify-center gap-4">
              <div className="flex items-center gap-2 opacity-50">
                <Shield className="w-4 h-4" />
                <span className="text-[10px] font-bold uppercase tracking-widest">Nusuk Pro Security</span>
              </div>
            </div>
          </div>
        </div>
      );
    }

    // Fixed: 'this.props' is available via inheritance from React.Component.
    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Shield, Upload, Play, Terminal, Settings, Download, 
  CheckCircle2, Loader2, Mail, Lock, Activity, 
  Cpu, Database, ExternalLink, UserPlus, Info, 
  Globe, Fingerprint, Zap, AlertTriangle, RefreshCw, XCircle, Edit3, Send, Bot, Wifi, WifiOff
} from 'lucide-react';
import { VisaRecord, RegistrationStatus } from './types';
import { PRIMARY_EMAIL, UNIFIED_PASSWORD } from './constants';
import { extractVisaData } from './services/geminiService';

const App: React.FC = () => {
  const [records, setRecords] = useState<VisaRecord[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [activeTab, setActiveTab] = useState<'monitor' | 'accounts' | 'telegram'>('monitor');
  const [error, setError] = useState<string | null>(null);

  // Telegram Bot States
  const [botToken, setBotToken] = useState<string>(localStorage.getItem('tg_bot_token') || '');
  const [isBotActive, setIsBotActive] = useState(false);
  const [lastUpdateId, setLastUpdateId] = useState<number>(0);
  const pollingRef = useRef<NodeJS.Timeout | null>(null);

  const [config, setConfig] = useState({
    email: PRIMARY_EMAIL,
    password: UNIFIED_PASSWORD,
    gateway: 'https://stealth-proxy.nusuk-api.com',
    threads: 3,
    solveCaptcha: true
  });

  const addLog = (id: string, message: string, type: 'info' | 'error' | 'success' | 'network' = 'info') => {
    const timestamp = new Date().toLocaleTimeString();
    setRecords(prev => prev.map(r => r.id === id ? {
      ...r,
      logs: [...r.logs, { timestamp, message, type }]
    } : r));
  };

  // --- Telegram Bot Logic ---
  const toggleBot = () => {
    if (isBotActive) {
      if (pollingRef.current) clearInterval(pollingRef.current);
      setIsBotActive(false);
    } else {
      if (!botToken) {
        setError("يرجى إدخال توكن البوت أولاً (من BotFather)");
        return;
      }
      localStorage.setItem('tg_bot_token', botToken);
      setIsBotActive(true);
      startPolling();
    }
  };

  const startPolling = () => {
    pollingRef.current = setInterval(async () => {
      try {
        const response = await fetch(`https://api.telegram.org/bot${botToken}/getUpdates?offset=${lastUpdateId + 1}&timeout=10`);
        const data = await response.json();

        if (data.ok && data.result.length > 0) {
          for (const update of data.result) {
            setLastUpdateId(update.update_id);
            if (update.message?.document) {
              const doc = update.message.document;
              if (doc.mime_type === 'application/pdf') {
                processTelegramFile(doc.file_id, update.message.chat.id, update.message.from.first_name);
              }
            } else if (update.message?.text === '/start') {
              sendTelegramMessage(update.message.chat.id, "أهلاً بك في بوت Nusuk Engine. أرسل ملفات التأشيرات PDF وسأقوم بمعالجتها فوراً.");
            }
          }
        }
      } catch (err) {
        console.error("TG Polling Error:", err);
      }
    }, 3000);
  };

  const processTelegramFile = async (fileId: string, chatId: number, sender: string) => {
    try {
      sendTelegramMessage(chatId, "⏳ جاري تحميل التأشيرة وتحليلها برمجياً...");

      const fileRes = await fetch(`https://api.telegram.org/bot${botToken}/getFile?file_id=${fileId}`);
      const fileData = await fileRes.json();
      const filePath = fileData.result.file_path;

      const downloadRes = await fetch(`https://api.telegram.org/file/bot${botToken}/${filePath}`);
      const blob = await downloadRes.blob();

      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = (reader.result as string).split(',')[1];
        try {
          const extractedData = await extractVisaData(base64);

          const newRecords: VisaRecord[] = extractedData.map(v => ({
            id: Math.random().toString(36).substr(2, 9),
            ...v,
            email: `${config.email.split('@')[0]}+ns${Math.floor(Math.random()*10000)}@${config.email.split('@')[1]}`,
            status: RegistrationStatus.READY,
            createdAt: new Date().toISOString(),
            logs: [{ timestamp: new Date().toLocaleTimeString(), message: `📥 مستلم من تلجرام بواسطة: ${sender}`, type: 'success' }],
            automationConfig: {
              proxy: `res-proxy-${Math.floor(Math.random()*999)}.net:8080`,
              userAgent: "Mozilla/5.0...",
              fingerprintId: `tg_${sender}_${Math.random().toString(36).substr(2, 5)}`,
              resolution: "1920x1080"
            }
          }));

          setRecords(prev => [...newRecords, ...prev]);
          sendTelegramMessage(chatId, `✅ تم بنجاح! تم استخراج بيانات: ${extractedData[0].fullName}. الحساب جاهز الآن في لوحة التحكم.`);
        } catch (e) {
          sendTelegramMessage(chatId, "❌ فشل تحليل الملف. تأكد من أنه ملف تأشيرة أصلي.");
        }
      };
      reader.readAsDataURL(blob);
    } catch (err) {
      sendTelegramMessage(chatId, "❌ حدث خطأ في الاتصال بالسيرفر.");
    }
  };

  const sendTelegramMessage = (chatId: number, text: string) => {
    fetch(`https://api.telegram.org/bot${botToken}/sendMessage`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: chatId, text: text })
    });
  };

  // --- Web Logic ---
  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    try {
      const reader = new FileReader();
      reader.onload = async (e) => {
        const base64 = (e.target?.result as string).split(',')[1];
        const data = await extractVisaData(base64);
        const newRecords: VisaRecord[] = data.map(v => ({
          id: Math.random().toString(36).substr(2, 9),
          ...v,
          email: `${config.email.split('@')[0]}+ns${Math.floor(Math.random()*10000)}@${config.email.split('@')[1]}`,
          status: RegistrationStatus.READY,
          createdAt: new Date().toISOString(),
          logs: [{ timestamp: new Date().toLocaleTimeString(), message: '✅ تم التحليل المباشر', type: 'success' }],
          automationConfig: { proxy: '...', userAgent: '...', fingerprintId: '...', resolution: '...' }
        }));
        setRecords(prev => [...newRecords, ...prev]);
        setIsProcessing(false);
      };
      reader.readAsDataURL(file);
    } catch (err) { setIsProcessing(false); }
  };

  const executeRegistration = (id: string) => {
    updateStatus(id, RegistrationStatus.HANDSHAKE);
    addLog(id, `🌐 بدء عملية الأتمتة...`, 'network');
    setTimeout(() => updateStatus(id, RegistrationStatus.AWAITING_OTP), 3000);
  };

  const updateStatus = (id: string, status: RegistrationStatus) => {
    setRecords(prev => prev.map(r => r.id === id ? { ...r, status } : r));
  };

  const updateEmail = (id: string, newEmail: string) => {
    setRecords(prev => prev.map(r => r.id === id ? { ...r, email: newEmail } : r));
  };

  return (
    <div className="min-h-screen bg-[#020617] text-slate-100 flex flex-col font-['Cairo']">
      {/* Header */}
      <header className="h-24 bg-[#0c111d]/50 backdrop-blur-3xl border-b border-white/5 flex items-center justify-between px-12 sticky top-0 z-[100]">
        <div className="flex items-center gap-6">
          <div className="bg-[#0f172a] p-4 rounded-2xl border border-white/10">
            <Zap className="w-8 h-8 text-emerald-400" />
          </div>
          <div>
            <h1 className="text-2xl font-black">NUSUK <span className="text-emerald-500">ENGINE</span></h1>
            <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest">Bot & AI Automation</p>
          </div>
        </div>

        <div className="flex bg-black/40 p-1.5 rounded-2xl border border-white/5">
