const StatusBadge: React.FC<{ status: RegistrationStatus }> = ({ status }) => {
  const map: Record<string, { label: string; color: string }> = {
    [RegistrationStatus.READY]: { label: 'جاهز', color: 'text-slate-400 border-white/10' },
    [RegistrationStatus.HANDSHAKE]: { label: 'جاري الاتصال', color: 'text-blue-400 border-blue-500/20' },
    [RegistrationStatus.AWAITING_OTP]: { label: 'انتظار الكود', color: 'text-amber-400 border-amber-500/20' },
    [RegistrationStatus.SUCCESS]: { label: 'مكتمل', color: 'text-emerald-400 border-emerald-500/20' },
  };
  const current = map[status] || map[RegistrationStatus.READY];
  return <span className={`px-4 py-1.5 rounded-full border text-[9px] font-black uppercase tracking-widest ${current.color}`}>{current.label}</span>;
};

