  // Telegram Bot States
  const [botToken, setBotToken] = useState<string>(localStorage.getItem('tg_bot_token') || '');
  const [isBotActive, setIsBotActive] = useState(false);
  const [lastUpdateId, setLastUpdateId] = useState<number>(0);
  // Fix: Using 'any' instead of 'NodeJS.Timeout' as it's not available in the browser environment
  const pollingRef = useRef<any>(null);

