  const toggleBot = () => {
    if (isBotActive) {
      if (pollingRef.current) clearInterval(pollingRef.current);
      setIsBotActive(false);
    } else {
      if (!botToken) {
        setError("يرجى إدخال توكن البوت أولاً (من BotFather)");
        return;
      }
      localStorage.setItem('tg_bot_token', botToken);
      setIsBotActive(true);
      startPolling();
    }
  };

  const startPolling = () => {
    pollingRef.current = setInterval(async () => {
      try {
        const response = await fetch(`https://api.telegram.org/bot${botToken}/getUpdates?offset=${lastUpdateId + 1}&timeout=10`);
        const data = await response.json();

        if (data.ok && data.result.length > 0) {
          for (const update of data.result) {
            setLastUpdateId(update.update_id);
            if (update.message?.document) {
              const doc = update.message.document;
              if (doc.mime_type === 'application/pdf') {
                processTelegramFile(doc.file_id, update.message.chat.id, update.message.from.first_name);
              }
            } else if (update.message?.text === '/start') {
              sendTelegramMessage(update.message.chat.id, "أهلاً بك في بوت Nusuk Engine. أرسل ملفات التأشيرات PDF وسأقوم بمعالجتها فوراً.");
