export enum TaskStatus {
  IDLE = 'IDLE',
  PROCESSING = 'PROCESSING',
  COMPLETED = 'COMPLETED',
  FAILED = 'FAILED'
}

export interface VisaData {
  passportNumber: string;
  visaNumber: string;
  fullName: string;
  nationality: string;
  dateOfBirth: string;
}

export interface AutomationTask {
  id: string;
  status: TaskStatus;
  data?: VisaData;
  error?: string;
  logs: string[];
  createdAt: number;
}

