import { GoogleGenAI, Type } from "@google/genai";
import { GEMINI_MODEL } from "../constants";
import { VisaData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const extractVisaInfo = async (base64Pdf: string): Promise<VisaData[]> => {
  try {
    const response = await ai.models.generateContent({
      model: GEMINI_MODEL,
      contents: {
        parts: [
          { inlineData: { mimeType: "application/pdf", data: base64Pdf } },
          { text: "Extract visa details for Nusuk registration. Return as JSON array." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              passportNumber: { type: Type.STRING },
              visaNumber: { type: Type.STRING },
              fullName: { type: Type.STRING },
              nationality: { type: Type.STRING },
              dateOfBirth: { type: Type.STRING }
            },
            required: ["passportNumber", "visaNumber", "fullName"]
          }
        }
      }
    });

    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Extraction Failed:", error);
    throw new Error("فشل استخراج البيانات من الملف");
  }
};

