        } catch (err: any) {
          setTasks(prev => prev.map(t => t.id === taskId ? {
            ...t,
            status: TaskStatus.FAILED,
            error: err.message,
            logs: [...t.logs, `❌ خطأ: ${err.message}`]
          } : t));
        }
      };
      reader.readAsDataURL(file);
    } finally {
      setIsUploading(false);
      if (e.target) e.target.value = '';
    }
