            <Zap className="w-6 h-6 text-black fill-current" />
          </div>
          <h1 className="text-xl font-black tracking-tighter text-white">{APP_NAME}</h1>
        </div>

        <nav className="flex-1 space-y-2">
          <NavItem 
            icon={<LayoutDashboard className="w-5 h-5" />} 
            label="لوحة التحكم" 
            active={activeView === 'dashboard'} 
            onClick={() => setActiveView('dashboard')} 
          />
          <NavItem 
            icon={<History className="w-5 h-5" />} 
            label="السجل التاريخي" 
            active={false} 
          />
          <NavItem 
            icon={<Settings className="w-5 h-5" />} 
            label="الإعدادات" 
            active={activeView === 'settings'} 
            onClick={() => setActiveView('settings')} 
          />
        </nav>

        <div className="mt-auto bg-white/5 rounded-2xl p-4 border border-white/5">
          <div className="flex items-center gap-3 mb-2">
            <ShieldCheck className="w-4 h-4 text-emerald-500" />
            <span className="text-[10px] font-bold uppercase tracking-widest opacity-50">نظام محمي</span>
          </div>
          <p className="text-[11px] leading-relaxed opacity-70">المحرك يعمل بأحدث تقنيات Gemini 3 Pro لضمان الدقة.</p>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-12 overflow-y-auto">
        <header className="flex justify-between items-end mb-12">
          <div>
            <h2 className="text-4xl font-black text-white mb-2">مرحباً بك</h2>
            <p className="text-slate-500">ابدأ برفع التأشيرات لبدء عملية الأتمتة.</p>
          </div>

          <label className="group relative cursor-pointer overflow-hidden rounded-2xl bg-emerald-500 px-8 py-4 transition-all hover:bg-emerald-400 active:scale-95 shadow-xl shadow-emerald-500/20">
            <div className="flex items-center gap-3 text-black font-black">
              {isUploading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Plus className="w-5 h-5" />}
              <span>إضافة تأشيرة جديدة</span>
            </div>
            <input type="file" className="hidden" accept="application/pdf" onChange={handleFileSelect} disabled={isUploading} />
          </label>
