        {activeView === 'dashboard' ? (
          <div className="grid grid-cols-1 gap-6">
            {tasks.length === 0 ? (
              <div className="h-96 border-2 border-dashed border-white/5 rounded-[2.5rem] flex flex-col items-center justify-center text-slate-600">
                <FileText className="w-16 h-16 mb-4 opacity-20" />
