                  <div className="flex items-center justify-between mb-6">
                    <div className="flex items-center gap-6">
                      <div className={`p-4 rounded-2xl ${task.status === TaskStatus.COMPLETED ? 'bg-emerald-500/10 text-emerald-500' : 'bg-blue-500/10 text-blue-500'}`}>
                        {task.status === TaskStatus.PROCESSING ? <Cpu className="w-8 h-8 animate-pulse" /> : <CheckCircle2 className="w-8 h-8" />}
                      </div>
                      <div>
                        <h3 className="text-xl font-black text-white">
                          {task.data?.fullName || 'جاري معالجة الملف...'}
                        </h3>
                        <p className="text-xs text-slate-500 font-mono mt-1">ID: {task.id} • {new Date(task.createdAt).toLocaleTimeString()}</p>
