                    <div className="flex items-center gap-2 mb-2 opacity-50">
                      <div className="w-1 h-1 bg-slate-400 rounded-full"></div>
                      <span className="text-[10px] font-bold uppercase tracking-widest">Logs</span>
                    </div>
                    <div className="space-y-1">
                      {task.logs.slice(-2).map((log, i) => (
                        <p key={i} className="text-[11px] text-slate-400 font-mono">{log}</p>
                      ))}
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        ) : (
          <div className="bg-[#0f0f0f] border border-white/5 rounded-3xl p-12 text-center">
            <Settings className="w-12 h-12 mx-auto mb-6 text-slate-600" />
            <h3 className="text-2xl font-black text-white mb-4">الإعدادات قيد التطوير</h3>
            <p className="text-slate-500 max-w-md mx-auto">هنا ستتمكن من تعديل البريد الإلكتروني الموحد، وكلمة المرور، وإعدادات الوكيل (Proxy).</p>
          </div>
        )}
      </main>
