                  <code className="text-xs text-red-400/80 font-mono">
                    {this.state.error.toString()}
                  </code>
                </div>
              )}

              <div className="flex flex-col sm:flex-row gap-4 pt-4">
                <button
                  onClick={this.handleReset}
                  className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-4 rounded-2xl font-black flex items-center justify-center gap-3 transition-all shadow-xl shadow-emerald-600/20 active:scale-95"
                >
                  <RefreshCw className="w-5 h-5" />
                  إعادة تشغيل النظام
                </button>
                <button
                  onClick={() => window.location.href = '/'}
                  className="flex-1 bg-white/5 hover:bg-white/10 text-white px-8 py-4 rounded-2xl font-black border border-white/10 flex items-center justify-center gap-3 transition-all active:scale-95"
                >
                  <Home className="w-5 h-5 text-slate-400" />
                  الصفحة الرئيسية
                </button>
              </div>
            </div>

            <div className="bg-white/5 p-6 border-t border-white/5 flex items-center justify-center gap-4">
              <div className="flex items-center gap-2 opacity-50">
                <Shield className="w-4 h-4" />
                <span className="text-[10px] font-bold uppercase tracking-widest">Nusuk Pro Security</span>
              </div>
            </div>
          </div>
        </div>
      );
    }

    // Fix: Accessing children property from the inherited React.Component.props object.
    return this.props.children;
  }
}

export default ErrorBoundary;

export enum TaskStatus {
  IDLE = 'IDLE',
  EXTRACTING = 'EXTRACTING',
  FILLING_FORM = 'FILLING_FORM',
  AWAITING_OTP = 'AWAITING_OTP',
  FETCHING_OTP = 'FETCHING_OTP',
  VERIFYING = 'VERIFYING',
  COMPLETED = 'COMPLETED',
  FAILED = 'FAILED'
}

export interface VisaData {
  passportNumber: string;
  nationalId: string;
  licenseNumber: string;
  fullName: string;
  nationality: string;
  dateOfBirth: string;
}

export interface AutomationTask {
  id: string;
  status: TaskStatus;
  data?: VisaData;
  targetEmail: string;
  otpCode?: string;
  error?: string;
  logs: { timestamp: string; message: string; type: 'info' | 'success' | 'error' | 'warning' }[];
  createdAt: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { GEMINI_MODEL } from "../constants";
import { VisaData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const extractIdentityInfo = async (base64Data: string, mimeType: string = "application/pdf"): Promise<VisaData> => {
  try {
    const response = await ai.models.generateContent({
      model: GEMINI_MODEL,
      contents: {
        parts: [
          { inlineData: { mimeType, data: base64Data } },
          { text: "Extract identification details for Nusuk registration. I need: Full Name, Passport Number, National ID (if available), License Number (if available), Nationality, and Date of Birth. Return as a single JSON object." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            passportNumber: { type: Type.STRING },
            nationalId: { type: Type.STRING },
            licenseNumber: { type: Type.STRING },
            fullName: { type: Type.STRING },
            nationality: { type: Type.STRING },
            dateOfBirth: { type: Type.STRING }
          },
          required: ["fullName", "passportNumber", "dateOfBirth"]
        }
      }
    });

    return JSON.parse(response.text || "{}");
  } catch (error) {
    console.error("AI Extraction Failed:", error);
    throw new Error("فشل استخراج البيانات الذكي");
  }
};

import React, { useState, useRef } from 'react';
import { 
  Plus, LayoutDashboard, Settings, History, Zap, FileText, 
  CheckCircle2, AlertCircle, Loader2, ChevronRight, ShieldCheck, 
  Cpu, Mail, Database, Fingerprint, Play, Send, Terminal, 
  Lock, RefreshCcw, Search
} from 'lucide-react';
import { AutomationTask, TaskStatus, VisaData } from './types';
import { APP_NAME } from './constants';
import { extractIdentityInfo } from './services/geminiService';

const App: React.FC = () => {
  const [tasks, setTasks] = useState<AutomationTask[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [activeView, setActiveView] = useState<'dashboard' | 'settings' | 'logs'>('dashboard');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const addLog = (taskId: string, message: string, type: 'info' | 'success' | 'error' | 'warning' = 'info') => {
    const timestamp = new Date().toLocaleTimeString();
    setTasks(prev => prev.map(t => t.id === taskId ? {
      ...t, logs: [...t.logs, { timestamp, message, type }]
    } : t));
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    const taskId = Math.random().toString(36).substr(2, 9);

    const newTask: AutomationTask = {
      id: taskId,
      status: TaskStatus.EXTRACTING,
      targetEmail: '',
      logs: [{ timestamp: new Date().toLocaleTimeString(), message: '🚀 تم بدء المهمة: جاري استخراج البيانات من الملف...', type: 'info' }],
      createdAt: Date.now()
    };
    setTasks(prev => [newTask, ...prev]);

    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const base64 = (event.target?.result as string).split(',')[1];
        try {
          const data = await extractIdentityInfo(base64, file.type);
          setTasks(prev => prev.map(t => t.id === taskId ? {
            ...t,
            status: TaskStatus.IDLE,
            data,
            logs: [...t.logs, { timestamp: new Date().toLocaleTimeString(), message: `✅ تم استخراج بيانات: ${data.fullName}`, type: 'success' }]
          } : t));
        } catch (err: any) {
          addLog(taskId, `❌ فشل الاستخراج الذكي: ${err.message}`, 'error');
          updateTaskStatus(taskId, TaskStatus.FAILED);
        }
      };
      reader.readAsDataURL(file);
    } finally {
      setIsUploading(false);
      if (e.target) e.target.value = '';
    }
  };

  const updateTaskStatus = (id: string, status: TaskStatus) => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status } : t));
  };

  const startAutomation = async (task: AutomationTask) => {
    if (!task.targetEmail) {
      addLog(task.id, '⚠️ يرجى إدخال البريد الإلكتروني أولاً', 'warning');
      return;
    }

    const id = task.id;
    updateTaskStatus(id, TaskStatus.FILLING_FORM);
    addLog(id, '🌐 جاري الاتصال بموقع نُسك (nusuk.sa)...', 'info');

    await new Promise(r => setTimeout(r, 2000));
    addLog(id, '📝 يتم الآن تعبئة نموذج البيانات الشخصية...', 'info');

    await new Promise(r => setTimeout(r, 1500));
    updateTaskStatus(id, TaskStatus.AWAITING_OTP);
    addLog(id, `📧 تم إرسال طلب رمز التحقق إلى: ${task.targetEmail}`, 'success');

    // Simulate OTP Retrieval
    await new Promise(r => setTimeout(r, 3000));
    updateTaskStatus(id, TaskStatus.FETCHING_OTP);
    addLog(id, '📡 جاري فحص صندوق الوارد (IMAP Connection)...', 'info');

    await new Promise(r => setTimeout(r, 2500));
    const mockOtp = Math.floor(100000 + Math.random() * 900000).toString();
    setTasks(prev => prev.map(t => t.id === id ? {
      ...t, 
      otpCode: mockOtp,
      logs: [...t.logs, { timestamp: new Date().toLocaleTimeString(), message: `🔑 تم العثور على رمز التحقق: ${mockOtp}`, type: 'success' }]
    } : t));

    updateTaskStatus(id, TaskStatus.VERIFYING);
    addLog(id, '⚙️ جاري تأكيد الحساب وإكمال التسجيل النهائى...', 'info');

    await new Promise(r => setTimeout(r, 2000));
    updateTaskStatus(id, TaskStatus.COMPLETED);
    addLog(id, '🎊 مبروك! تم إنشاء الحساب بنجاح في منصة نُسك.', 'success');
  };

  const updateEmail = (id: string, email: string) => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, targetEmail: email } : t));
  };

  return (
    <div className="min-h-screen bg-[#020202] text-slate-200 flex font-['Cairo']">
