      <aside className="w-80 bg-[#080808] border-l border-white/5 flex flex-col p-8 sticky top-0 h-screen">
        <div className="flex items-center gap-4 mb-16">
          <div className="bg-emerald-500 shadow-lg shadow-emerald-500/20 p-2.5 rounded-xl">
            <Zap className="w-7 h-7 text-black fill-current" />
          </div>
          <div>
            <h1 className="text-2xl font-black tracking-tighter text-white">نُسك أوتو</h1>
            <p className="text-[10px] font-bold text-emerald-500/70 uppercase tracking-[0.2em]">Automation Engine</p>
          </div>
        </div>

        <nav className="flex-1 space-y-3">
          <NavItem icon={<LayoutDashboard />} label="الرصد المباشر" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavItem icon={<Terminal />} label="سجل الأوامر" active={activeView === 'logs'} onClick={() => setActiveView('logs')} />
          <NavItem icon={<History />} label="الأرشيف" active={false} />
          <NavItem icon={<Settings />} label="الإعدادات" active={activeView === 'settings'} onClick={() => setActiveView('settings')} />
        </nav>

        <div className="mt-auto space-y-4">
           <div className="bg-white/5 rounded-2xl p-5 border border-white/5 backdrop-blur-md">
             <div className="flex items-center gap-3 mb-3">
               <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
               <span className="text-xs font-black text-white">حالة الخادم: متصل</span>
             </div>
             <p className="text-[11px] text-slate-500 leading-relaxed font-medium">نظام الأتمتة يعمل حالياً عبر خوادم محلية مشفرة لضمان أمن البيانات.</p>
           </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-12 overflow-y-auto custom-scrollbar">
        <header className="flex justify-between items-start mb-16">
          <div className="space-y-2">
            <h2 className="text-5xl font-black text-white tracking-tight">لوحة التحكم</h2>
            <div className="flex items-center gap-4 text-slate-500">
               <span className="flex items-center gap-2 text-sm bg-white/5 px-3 py-1 rounded-lg border border-white/5">
                 <Database className="w-4 h-4" /> {tasks.length} مهام نشطة
               </span>
               <span className="flex items-center gap-2 text-sm bg-white/5 px-3 py-1 rounded-lg border border-white/5">
                 <ShieldCheck className="w-4 h-4 text-emerald-500" /> مشفر بـ AES-256
               </span>
            </div>
          </div>

          <button 
            onClick={() => fileInputRef.current?.click()}
            className="group relative px-10 py-5 rounded-2xl bg-emerald-500 text-black font-black text-lg transition-all hover:bg-emerald-400 hover:scale-[1.02] active:scale-95 shadow-2xl shadow-emerald-500/20 flex items-center gap-4"
          >
            {isUploading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Plus className="w-6 h-6" />}
            <span>استيراد بيانات جديدة</span>
            <input type="file" ref={fileInputRef} className="hidden" accept=".pdf,image/*" onChange={handleFileUpload} />
          </button>
