                <p className="text-slate-600 mt-2">قم برفع ملفات الهوية أو الجوازات لتبدأ الأتمتة</p>
              </div>
            </div>
          ) : (
            tasks.map(task => (
              <div key={task.id} className={`bg-[#0c0c0c] border rounded-[2.5rem] p-10 transition-all duration-500 shadow-2xl ${task.status === TaskStatus.COMPLETED ? 'border-emerald-500/30' : 'border-white/5'}`}>
                <div className="flex items-center justify-between mb-10">
