import { GoogleGenAI, Type } from "@google/genai";
import { GEMINI_MODEL } from "../constants";
import { VisaData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const extractBulkIdentityInfo = async (base64Data: string, mimeType: string): Promise<VisaData[]> => {
  try {
    const response = await ai.models.generateContent({
      model: GEMINI_MODEL,
      contents: {
        parts: [
          { inlineData: { mimeType, data: base64Data } },
          { text: "Extract ALL identification details from this document. It may contain multiple people. For each person, I need: Full Name, Passport Number, National ID, License Number, Nationality, and Date of Birth. Return as an ARRAY of objects." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              passportNumber: { type: Type.STRING },
              nationalId: { type: Type.STRING },
              licenseNumber: { type: Type.STRING },
              fullName: { type: Type.STRING },
              nationality: { type: Type.STRING },
              dateOfBirth: { type: Type.STRING }
            },
            required: ["fullName", "passportNumber"]
          }
        }
      }
    });

    const text = response.text || "[]";
    return JSON.parse(text);
  } catch (error) {
    console.error("Bulk AI Extraction Failed:", error);
    throw new Error("فشل استخراج البيانات الجماعي");
  }
};

import React, { useState, useRef } from 'react';
import { 
  Plus, LayoutDashboard, Settings, History, Zap, 
  CheckCircle2, AlertCircle, Loader2, ChevronRight, ShieldCheck, 
  Cpu, Mail, Database, Fingerprint, Play, Send, Terminal, 
  Lock, RefreshCcw, Search, Camera, Key, Smartphone, Users
} from 'lucide-react';
import { AutomationTask, TaskStatus, VisaData, GlobalSettings } from './types';
import { extractBulkIdentityInfo } from './services/geminiService';

const App: React.FC = () => {
  const [tasks, setTasks] = useState<AutomationTask[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [globalSettings, setGlobalSettings] = useState<GlobalSettings>({
    bulkEmails: '',
    emailPassword: '',
    nusukAccountPassword: 'Password@123'
  });

  const [activeView, setActiveView] = useState<'dashboard' | 'config'>('dashboard');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // مولد أرقام هواتف سعودية عشوائية متوافق مع نُسك
  const generateRandomPhone = () => {
    const start = "05";
    const digits = Math.floor(10000000 + Math.random() * 90000000).toString();
    return start + digits;
  };

  const addLog = (taskId: string, message: string, type: 'info' | 'success' | 'error' | 'warning' = 'info') => {
    const timestamp = new Date().toLocaleTimeString();
    setTasks(prev => prev.map(t => t.id === taskId ? {
      ...t, logs: [...t.logs, { timestamp, message, type }]
    } : t));
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    const emailsList = globalSettings.bulkEmails.split(/[\n,]+/).map(e => e.trim()).filter(e => e);

    if (emailsList.length === 0) {
      alert("يرجى إدخال قائمة الإيميلات أولاً في قسم الإعدادات");
      setIsProcessing(false);
      return;
    }

    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const base64 = (event.target?.result as string).split(',')[1];
        try {
          const extractedData = await extractBulkIdentityInfo(base64, file.type);

          const newTasks: AutomationTask[] = extractedData.map((data, index) => ({
            id: Math.random().toString(36).substr(2, 9),
            status: TaskStatus.READY_TO_START,
            data: { ...data, phoneNumber: generateRandomPhone() },
