    </div>
    <p className="text-xs font-bold text-white truncate">{value || '---'}</p>
  </div>
);

const StatusBadge: React.FC<{ status: TaskStatus }> = ({ status }) => {
  const configs: any = {
    [TaskStatus.READY_TO_START]: { label: 'جاهز', color: 'text-emerald-400 border-emerald-500/20 bg-emerald-500/5' },
    [TaskStatus.FILLING_FORM]: { label: 'تعبئة النموذج', color: 'text-blue-400 border-blue-500/20 bg-blue-500/5' },
    [TaskStatus.AWAITING_OTP]: { label: 'انتظار الكود', color: 'text-amber-400 border-amber-500/20 bg-amber-500/5' },
    [TaskStatus.COMPLETED]: { label: 'ناجح', color: 'text-emerald-400 border-emerald-500/20 bg-emerald-500/5' },
  };
  const config = configs[status] || { label: 'تحليل', color: 'text-slate-400 border-white/10 bg-white/5' };
  return (
    <div className={`px-4 py-1.5 rounded-full border text-[9px] font-black uppercase ${config.color}`}>
      {config.label}
    </div>
  );
};

export default App;

