          <NavItem icon={<Settings />} label="إعدادات الأتمتة" active={activeView === 'config'} onClick={() => setActiveView('config')} />
        </nav>

        <div className="bg-white/5 rounded-2xl p-5 border border-white/5 mt-auto">
          <p className="text-[10px] text-slate-500 uppercase font-black tracking-widest mb-2">تأمين البيانات</p>
          <div className="flex items-center gap-2 text-emerald-500 text-xs font-bold">
            <ShieldCheck className="w-4 h-4" />
            اتصال آمن بنظام الأتمتة
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 h-screen overflow-y-auto p-4 md:p-12 pb-32 custom-scrollbar">
        {activeView === 'dashboard' ? (
          <>
            <header className="flex flex-col md:flex-row justify-between items-start gap-6 mb-12">
              <div className="space-y-2">
                <h2 className="text-3xl md:text-5xl font-black text-white">العمليات الميدانية</h2>
                <p className="text-slate-500 max-w-lg">تسجيل حسابات المعتمرين آلياً بناءً على ملفات التأشيرات وقائمة الإيميلات.</p>
              </div>

              <div className="flex flex-wrap gap-3 w-full md:w-auto">
                <button 
