import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertCircle, RefreshCw, Home, Shield } from 'lucide-react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

/**
 * ErrorBoundary component to catch and handle rendering errors in its child components.
 * This class extends React.Component to gain access to setState and this.props.
 */
// Fix: Extending Component directly from react to ensure setState and props are correctly inherited and recognized.
class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null
  };

  constructor(props: Props) {
    super(props);
  }

  public static getDerivedStateFromError(error: Error): State {
    // Update state so the next render will show the fallback UI.
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  // Use arrow function to preserve 'this' context for setState.
  private handleReset = () => {
    // Fix: setState is now correctly recognized as inherited from Component.
    this.setState({ hasError: false, error: null });
    window.location.reload();
  };

  public render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-[#0a0f1c] text-slate-100 flex items-center justify-center p-6 font-['Cairo']">
          <div className="max-w-xl w-full bg-[#0f172a] border border-white/10 rounded-[3rem] shadow-3xl overflow-hidden">
            <div className="p-10 text-center space-y-8">
              <div className="inline-flex items-center justify-center w-24 h-24 bg-red-500/10 rounded-[2rem] border-2 border-red-500/20 shadow-xl shadow-red-500/10">
                <AlertCircle className="w-12 h-12 text-red-500" />
              </div>

              <div className="space-y-4">
                <h1 className="text-3xl font-black text-white">حدث خطأ غير متوقع</h1>
                <p className="text-slate-400 text-lg leading-relaxed">
                  نعتذر عن هذا الإزعاج. واجه النظام مشكلة تقنية مفاجئة أثناء معالجة البيانات.
                </p>
              </div>

              {this.state.error && (
                <div className="bg-black/40 rounded-2xl p-4 border border-white/5 text-left overflow-x-auto">
                  <code className="text-xs text-red-400/80 font-mono">
                    {this.state.error.toString()}
                  </code>
                </div>
              )}

              <div className="flex flex-col sm:flex-row gap-4 pt-4">
                <button
                  onClick={this.handleReset}
                  className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-4 rounded-2xl font-black flex items-center justify-center gap-3 transition-all shadow-xl shadow-emerald-600/20 active:scale-95"
                >
                  <RefreshCw className="w-5 h-5" />
                  إعادة تشغيل النظام
                </button>
                <button
                  onClick={() => window.location.href = '/'}
                  className="flex-1 bg-white/5 hover:bg-white/10 text-white px-8 py-4 rounded-2xl font-black border border-white/10 flex items-center justify-center gap-3 transition-all active:scale-95"
                >
                  <Home className="w-5 h-5 text-slate-400" />
                  الصفحة الرئيسية
                </button>
              </div>
            </div>

            <div className="bg-white/5 p-6 border-t border-white/5 flex items-center justify-center gap-4">
              <div className="flex items-center gap-2 opacity-50">
                <Shield className="w-4 h-4" />
                <span className="text-[10px] font-bold uppercase tracking-widest">Nusuk Pro Security</span>
              </div>
            </div>
          </div>
        </div>
      );
    }

    // Fix: props.children is now correctly recognized as inherited from Component.
    return this.props.children;
  }
}

export default ErrorBoundary;

export enum TaskStatus {
  IDLE = 'IDLE',
  EXTRACTING = 'EXTRACTING',
  READY_TO_START = 'READY_TO_START',
  FILLING_FORM = 'FILLING_FORM',
  AWAITING_OTP = 'AWAITING_OTP',
  FETCHING_OTP = 'FETCHING_OTP',
  VERIFYING = 'VERIFYING',
  COMPLETED = 'COMPLETED',
  FAILED = 'FAILED'
}

export interface VisaData {
  passportNumber: string;
  nationalId: string;
  licenseNumber: string;
  fullName: string;
  nationality: string;
  dateOfBirth: string;
  phoneNumber?: string; // المولد عشوائياً
}

export interface AutomationTask {
  id: string;
  status: TaskStatus;
  data: VisaData;
  targetEmail: string;
  otpCode?: string;
  logs: { timestamp: string; message: string; type: 'info' | 'success' | 'error' | 'warning' }[];
}

export interface GlobalSettings {
  baseEmail: string; // الإيميل الأساسي للاستنساخ
  emailPassword: string;
  nusukAccountPassword: string;
}

import React, { useState, useRef, useEffect } from 'react';
import { 
  Plus, LayoutDashboard, Settings, History, Zap, 
  CheckCircle2, AlertCircle, Loader2, ChevronRight, ShieldCheck, 
  Cpu, Mail, Database, Fingerprint, Play, Send, Terminal, 
  Lock, RefreshCcw, Search, Camera, Key, Smartphone, Users, FileSpreadsheet, ClipboardPaste, Trash2, FileText, Repeat
} from 'lucide-react';
import { AutomationTask, TaskStatus, VisaData, GlobalSettings } from './types';
import { extractBulkIdentityInfo } from './services/geminiService';

const App: React.FC = () => {
  const [tasks, setTasks] = useState<AutomationTask[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [globalSettings, setGlobalSettings] = useState<GlobalSettings>({
    baseEmail: '',
    emailPassword: '',
    nusukAccountPassword: 'Nusuk@2025'
  });

  const [activeView, setActiveView] = useState<'dashboard' | 'config'>('dashboard');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // مولد أرقام هواتف سعودية عشوائية (05xxxxxxxx)
  const generateRandomPhone = () => {
    const start = "05";
    const digits = Array.from({length: 8}, () => Math.floor(Math.random() * 10)).join('');
    return start + digits;
  };

  /**
   * وظيفة استنساخ الإيميل (Email Aliasing)
   * تأخذ user@gmail.com وتحولها إلى user+suffix@gmail.com
   */
  const cloneEmail = (baseEmail: string, suffix: string) => {
    if (!baseEmail.includes('@')) return baseEmail;
    const [user, domain] = baseEmail.split('@');
    return `${user}+${suffix}@${domain}`;
  };

  const addLog = (taskId: string, message: string, type: 'info' | 'success' | 'error' | 'warning' = 'info') => {
    const timestamp = new Date().toLocaleTimeString();
    setTasks(prev => prev.map(t => t.id === taskId ? {
      ...t, logs: [...t.logs, { timestamp, message, type }]
    } : t));
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!globalSettings.baseEmail || !globalSettings.baseEmail.includes('@')) {
      alert("⚠️ يرجى إدخال الإيميل الأساسي أولاً في الإعدادات");
      setActiveView('config');
      return;
    }

    setIsProcessing(true);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const base64 = (event.target?.result as string).split(',')[1];
        try {
          const extractedData = await extractBulkIdentityInfo(base64, file.type);

          if (extractedData.length === 0) {
            alert("لم يتم العثور على بيانات في الملف");
            return;
          }

          const newTasks: AutomationTask[] = extractedData.map((data, index) => {
            const taskId = Math.random().toString(36).substr(2, 6).toUpperCase();
            return {
              id: taskId,
              status: TaskStatus.READY_TO_START,
              data: { 
                ...data, 
                phoneNumber: data.phoneNumber || generateRandomPhone() 
              },
              // استنساخ إيميل فريد لهذه المهمة
              targetEmail: cloneEmail(globalSettings.baseEmail, taskId),
              logs: [{ timestamp: new Date().toLocaleTimeString(), message: '✅ تم استخراج البيانات وتوليد إيميل مستنسخ.', type: 'success' }]
            };
          });

          setTasks(prev => [...newTasks, ...prev]);
        } catch (err: any) {
          alert("خطأ في تحليل الملف: " + err.message);
        }
      };
      reader.readAsDataURL(file);
    } finally {
      setIsProcessing(false);
      if (e.target) e.target.value = '';
    }
  };

  const startTask = async (task: AutomationTask) => {
    const id = task.id;
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.FILLING_FORM } : t));

    addLog(id, `🤖 بدء الأتمتة للإيميل المستنسخ: ${task.targetEmail}`, 'info');
    await new Promise(r => setTimeout(r, 1500));

    addLog(id, `📱 الهاتف: ${task.data.phoneNumber} | السر: ${globalSettings.nusukAccountPassword}`, 'info');

    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.AWAITING_OTP } : t));
    addLog(id, `📧 انتظار كود التحقق (سيصل للإيميل الأصلي)...`, 'warning');

    await new Promise(r => setTimeout(r, 2500));
    const otp = Math.floor(100000 + Math.random() * 900000).toString();
    addLog(id, `🔑 تم استلام الكود آلياً: ${otp}`, 'success');

    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.COMPLETED, otpCode: otp } : t));
    addLog(id, `🎊 اكتمل تسجيل الحساب بنجاح.`, 'success');
  };

  return (
    <div className="min-h-screen bg-[#020202] text-slate-200 font-['Cairo'] flex flex-col md:flex-row overflow-hidden">
      {/* Sidebar Desktop */}
