        </nav>

        <div className="bg-white/5 rounded-2xl p-5 border border-white/5 mt-auto">
          <p className="text-[10px] text-slate-500 uppercase font-black tracking-widest mb-2">تأمين البيانات</p>
          <div className="flex items-center gap-2 text-emerald-500 text-xs font-bold">
            <ShieldCheck className="w-4 h-4" />
            نظام استنساخ آمن (Aliasing)
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 h-screen overflow-y-auto p-4 md:p-12 pb-32 custom-scrollbar">
        {activeView === 'dashboard' ? (
          <>
            <header className="flex flex-col md:flex-row justify-between items-start gap-6 mb-12">
              <div className="space-y-2">
                <h2 className="text-3xl md:text-5xl font-black text-white">العمليات</h2>
                <p className="text-slate-500 max-w-lg">ارفع ملف التأشيرات، وسيقوم النظام بتوليد إيميل مستنسخ لكل شخص تلقائياً.</p>
              </div>

              <div className="flex flex-wrap gap-3 w-full md:w-auto">
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="flex-1 md:flex-none bg-emerald-500 text-black px-8 py-4 rounded-2xl font-black flex items-center justify-center gap-3 active:scale-95 transition-all shadow-xl shadow-emerald-500/20"
                >
                  {isProcessing ? <Loader2 className="animate-spin" /> : <Plus />}
                  رفع تأشيرات
                  <input type="file" ref={fileInputRef} className="hidden" accept=".pdf,.xlsx,.xls,.csv,image/*" onChange={handleFileUpload} />
                </button>
                {tasks.length > 0 && (
                  <button onClick={() => setTasks([])} className="p-4 bg-red-500/10 text-red-500 border border-red-500/20 rounded-2xl active:scale-95">
                    <Trash2 size={24} />
                  </button>
                )}
              </div>
