            <div className="grid grid-cols-1 gap-6">
              {tasks.length === 0 ? (
                <div className="h-[400px] border-2 border-dashed border-white/5 rounded-[2.5rem] flex flex-col items-center justify-center text-slate-600 bg-white/[0.01]">
