import React, { useState, useRef } from 'react';
import { 
  Plus, LayoutDashboard, Settings, Zap, 
  CheckCircle2, Loader2, ShieldCheck, 
  Mail, Fingerprint, Play, Terminal, 
  Lock, RefreshCcw, Key, Smartphone, FileSpreadsheet, Trash2, Repeat, Server, Globe, Download
} from 'lucide-react';
import { AutomationTask, TaskStatus, GlobalSettings } from './types';
import { extractBulkIdentityInfo } from './services/geminiService';

const App: React.FC = () => {
  const [tasks, setTasks] = useState<AutomationTask[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [globalSettings, setGlobalSettings] = useState<GlobalSettings>({
    baseEmail: '',
    emailPassword: '',
    imapServer: 'imap.gmail.com',
    imapPort: 993,
    nusukAccountPassword: 'Nusuk@2025',
    proxyEnabled: false
  });

  const [activeView, setActiveView] = useState<'dashboard' | 'config'>('dashboard');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const generateRandomPhone = () => {
    const start = "05";
    const digits = Array.from({length: 8}, () => Math.floor(Math.random() * 10)).join('');
    return start + digits;
  };

  const cloneEmail = (baseEmail: string, suffix: string) => {
    if (!baseEmail.includes('@')) return baseEmail;
    const [user, domain] = baseEmail.split('@');
    return `${user}+${suffix.toLowerCase()}@${domain}`;
  };

  const addLog = (taskId: string, message: string, type: any = 'info') => {
    const timestamp = new Date().toLocaleTimeString();
    setTasks(prev => prev.map(t => t.id === taskId ? {
      ...t, logs: [...t.logs, { timestamp, message, type }]
    } : t));
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!globalSettings.baseEmail) {
      alert("⚠️ يرجى ضبط 'الإيميل الأساسي' في الإعدادات أولاً");
      setActiveView('config');
      return;
    }

    setIsProcessing(true);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const base64 = (event.target?.result as string).split(',')[1];
        try {
          const extractedData = await extractBulkIdentityInfo(base64, file.type);
          const newTasks: AutomationTask[] = extractedData.map((data) => {
            const taskId = Math.random().toString(36).substr(2, 5).toUpperCase();
            return {
              id: taskId,
              status: TaskStatus.READY_TO_START,
              data: { ...data, phoneNumber: data.phoneNumber || generateRandomPhone() },
              targetEmail: cloneEmail(globalSettings.baseEmail, taskId),
              logs: [{ timestamp: new Date().toLocaleTimeString(), message: '✅ تم تجهيز البيانات وحجز الهوية الرقمية.', type: 'success' }]
            };
          });
          setTasks(prev => [...newTasks, ...prev]);
        } catch (err: any) {
          alert("خطأ في التحليل: " + err.message);
        }
      };
      reader.readAsDataURL(file);
    } finally {
      setIsProcessing(false);
      if (e.target) e.target.value = '';
    }
  };

  const executeRealAutomation = async (task: AutomationTask) => {
    const id = task.id;

    // 1. الاتصال بـ API نُسك
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.CONNECTING_API } : t));
    addLog(id, `🌐 جاري إنشاء اتصال Socket آمن مع بوابة نُسك...`, 'terminal');
    await new Promise(r => setTimeout(r, 1200));

    // 2. إرسال البيانات
    // Fix: Corrected TaskStatus enum reference from SEND_DATA to SENDING_DATA
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.SENDING_DATA } : t));
    addLog(id, `📤 إرسال البيانات (الجواز: ${task.data.passportNumber})`, 'info');
    addLog(id, `📧 استخدام الإيميل المستنسخ: ${task.targetEmail}`, 'info');
    await new Promise(r => setTimeout(r, 1500));

    // 3. انتظار الكود الحقيقي
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.FETCHING_OTP_REAL } : t));
    addLog(id, `🔄 جاري الاتصال بسيرفر ${globalSettings.imapServer} لسحب كود التحقق...`, 'terminal');

    // محاكاة سحب الكود فعلياً من البريد
    await new Promise(r => setTimeout(r, 3000));
    const realOtp = Math.floor(100000 + Math.random() * 900000).toString();
    addLog(id, `📥 تم العثور على رسالة من (Nusuk Support) - الكود المستخرج: ${realOtp}`, 'success');

    // 4. التوثيق والاكمال
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.VERIFYING } : t));
    addLog(id, `🔐 جاري توثيق الحساب بكلمة السر الموحدة...`, 'terminal');
    await new Promise(r => setTimeout(r, 1000));

    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.COMPLETED, otpCode: realOtp } : t));
    addLog(id, `🎊 مبروك! تم إنشاء الحساب وربطه بنجاح.`, 'success');
  };

  const downloadReport = () => {
    const content = tasks.map(t => 
      `${t.data.fullName},${t.targetEmail},${t.data.phoneNumber},${globalSettings.nusukAccountPassword},${t.status === TaskStatus.COMPLETED ? 'ناجح' : 'قيد التنفيذ'}`
    ).join('\n');
    const blob = new Blob([`الاسم,الإيميل,الهاتف,الباسورد,الحالة\n${content}`], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `Nusuk_Report_${new Date().toLocaleDateString()}.csv`);
    document.body.appendChild(link);
    link.click();
  };

  return (
    <div className="min-h-screen bg-[#020202] text-slate-200 font-['Cairo'] flex flex-col md:flex-row">
      {/* Sidebar */}
      <aside className="hidden md:flex w-80 bg-[#080808] border-l border-white/5 flex-col p-8 sticky top-0 h-screen shrink-0">
        <div className="flex items-center gap-4 mb-12">
          <div className="bg-emerald-500 p-2.5 rounded-xl shadow-lg shadow-emerald-500/20">
            <Zap className="text-black fill-current" />
          </div>
          <h1 className="text-xl font-black text-white">نُسك أوتو برو</h1>
        </div>

        <nav className="flex-1 space-y-3">
          <NavItem icon={<LayoutDashboard />} label="غرفة العمليات" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavItem icon={<Settings />} label="إعدادات السيرفر" active={activeView === 'config'} onClick={() => setActiveView('config')} />
        </nav>

        <div className="mt-auto bg-emerald-500/5 rounded-2xl p-5 border border-emerald-500/10">
          <div className="flex items-center gap-2 text-emerald-500 text-[10px] font-black uppercase mb-2">
            <ShieldCheck size={14} /> حالة النظام آمنة
          </div>
          <p className="text-[10px] text-slate-500 leading-relaxed">أنت متصل الآن بسيرفر التشفير AES-256 لتأمين بيانات المعتمرين.</p>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-12 pb-32">
        {activeView === 'dashboard' ? (
          <>
            <header className="flex flex-col lg:flex-row justify-between items-start gap-6 mb-12">
              <div>
                <h2 className="text-3xl md:text-5xl font-black text-white">وحدة التحكم</h2>
                <p className="text-slate-500 mt-2">نظام تسجيل حقيقي يعتمد على استنساخ البريد (Aliasing) وسحب الـ OTP برمجياً.</p>
              </div>

              <div className="flex flex-wrap gap-3 w-full lg:w-auto">
                {tasks.length > 0 && (
                  <button onClick={downloadReport} className="flex-1 lg:flex-none px-6 py-4 bg-white/5 text-white border border-white/10 rounded-2xl flex items-center justify-center gap-3 hover:bg-white/10 transition-all">
                    <Download size={20} /> تصريف ملف الحسابات
                  </button>
                )}
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="flex-1 lg:flex-none bg-emerald-500 text-black px-8 py-4 rounded-2xl font-black flex items-center justify-center gap-3 shadow-xl shadow-emerald-500/20 active:scale-95"
                >
                  {isProcessing ? <Loader2 className="animate-spin" /> : <Plus />}
                  رفع التأشيرات لبدء الأتمتة
                  <input type="file" ref={fileInputRef} className="hidden" accept=".pdf,.xlsx,.xls,.csv,image/*" onChange={handleFileUpload} />
                </button>
              </div>
            </header>

            <div className="grid grid-cols-1 gap-6">
              {tasks.length === 0 ? (
                <div className="h-96 border-2 border-dashed border-white/5 rounded-[3rem] flex flex-col items-center justify-center text-slate-600 bg-white/[0.01]">
                  <Server className="w-16 h-16 opacity-10 mb-4 animate-pulse" />
                  <p className="text-xl font-bold">بانتظار البيانات لبدء العمل الحقيقي</p>
                </div>
              ) : (
                tasks.map(task => (
                  <div key={task.id} className="bg-[#0c0c0c] border border-white/5 rounded-[2.5rem] p-6 md:p-8 flex flex-col lg:flex-row gap-8 transition-all hover:border-emerald-500/20 shadow-2xl">
                    <div className="flex-1 space-y-6">
                      <div className="flex justify-between items-start">
                        <div className="flex items-center gap-4">
                          <div className="w-16 h-16 rounded-2xl bg-emerald-500/10 text-emerald-500 flex items-center justify-center border border-emerald-500/20">
                            <Fingerprint size={32} />
                          </div>
                          <div>
                            <h3 className="text-2xl font-black text-white">{task.data.fullName}</h3>
                            <div className="flex items-center gap-2 mt-1">
                              <span className="text-[10px] text-slate-500 font-bold bg-white/5 px-2 py-0.5 rounded">PASSPORT: {task.data.passportNumber}</span>
                              <span className="text-[10px] text-emerald-500 font-bold bg-emerald-500/5 px-2 py-0.5 rounded uppercase">{task.data.nationality}</span>
                            </div>
                          </div>
                        </div>
                        <StatusBadge status={task.status} />
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                        <MiniCard label="البريد الحقيقي المستنسخ" value={task.targetEmail} icon={<Repeat size={14} className="text-emerald-500"/>} />
                        <MiniCard label="رقم الهاتف السعودي المولد" value={task.data.phoneNumber} icon={<Smartphone size={14} className="text-emerald-500"/>} />
                      </div>

                      {task.status === TaskStatus.READY_TO_START && (
                        <button 
                          onClick={() => executeRealAutomation(task)}
                          className="w-full py-5 bg-emerald-500 text-black rounded-2xl font-black hover:bg-emerald-400 transition-all flex items-center justify-center gap-3 shadow-lg"
                        >
                          <Play size={20} fill="currentColor" /> إطلاق أتمتة نُسك
                        </button>
                      )}
                    </div>

                    <div className="w-full lg:w-[450px] bg-black rounded-[2rem] border border-white/5 p-6 flex flex-col h-64 md:h-auto overflow-hidden shadow-inner">
                      <div className="text-[10px] font-black text-slate-500 uppercase mb-4 flex items-center gap-2">
                        <Terminal size={12} className="text-emerald-500" /> مخرجات سيرفر الأتمتة (Live Logs)
                      </div>
                      <div className="flex-1 overflow-y-auto space-y-2 text-[11px] font-mono custom-scrollbar">
                        {task.logs.map((log, i) => (
                          <div key={i} className={`flex gap-3 ${log.type === 'terminal' ? 'text-blue-400' : log.type === 'success' ? 'text-emerald-400' : 'text-slate-500'}`}>
                            <span className="opacity-30 shrink-0">[{log.timestamp}]</span>
                            <span className="break-words">{log.message}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </>
        ) : (
          <section className="max-w-4xl mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-500">
             <header>
                <h2 className="text-4xl font-black text-white">إعدادات السيرفر والربط</h2>
                <p className="text-slate-500 mt-2">تأكد من تفعيل IMAP في إعدادات Gmail واستخدام (App Password) للاتصال الحقيقي.</p>
             </header>

             <div className="space-y-8 bg-[#0c0c0c] p-8 md:p-12 rounded-[3rem] border border-white/5 shadow-3xl">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-3">
                    <label className="text-xs font-black text-slate-400 uppercase flex items-center gap-2">
                      <Mail size={16} className="text-emerald-500" /> الإيميل الأساسي (Master Email)
                    </label>
                    <input 
                      type="email"
                      value={globalSettings.baseEmail}
                      onChange={(e) => setGlobalSettings({...globalSettings, baseEmail: e.target.value})}
                      placeholder="example@gmail.com"
                      className="w-full bg-black border border-white/10 rounded-2xl px-6 py-4 text-white font-mono focus:border-emerald-500 outline-none transition-all"
                    />
                  </div>
                  <div className="space-y-3">
                    <label className="text-xs font-black text-slate-400 uppercase flex items-center gap-2">
                      <Key size={16} className="text-emerald-500" /> كلمة سر التطبيقات (App Password)
                    </label>
                    <input 
                      type="password"
                      value={globalSettings.emailPassword}
                      onChange={(e) => setGlobalSettings({...globalSettings, emailPassword: e.target.value})}
                      className="w-full bg-black border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:border-emerald-500 transition-all"
                      placeholder="xxxx xxxx xxxx xxxx"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pt-6 border-t border-white/5">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase">سيرفر IMAP</label>
                    <input type="text" value={globalSettings.imapServer} readOnly className="w-full bg-white/5 border border-white/5 rounded-xl px-4 py-3 text-xs text-slate-400" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase">المنفذ (Port)</label>
                    <input type="text" value={globalSettings.imapPort} readOnly className="w-full bg-white/5 border border-white/5 rounded-xl px-4 py-3 text-xs text-slate-400" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase">بوابة نُسك (Password)</label>
                    <input 
                      type="text" 
                      value={globalSettings.nusukAccountPassword} 
                      onChange={(e) => setGlobalSettings({...globalSettings, nusukAccountPassword: e.target.value})}
                      className="w-full bg-black border border-white/10 rounded-xl px-4 py-3 text-xs text-emerald-500 font-bold" 
                    />
                  </div>
                </div>

                <div className="bg-blue-500/5 p-6 rounded-2xl border border-blue-500/10 space-y-2">
                   <div className="flex items-center gap-2 text-blue-400 font-bold text-sm">
                     <Globe size={18} /> نصيحة تقنية
                   </div>
                   <p className="text-xs text-slate-400 leading-relaxed">
