                   </p>
                </div>

                <button 
                  onClick={() => setActiveView('dashboard')}
                  className="w-full py-5 bg-emerald-500 text-black font-black rounded-2xl shadow-xl shadow-emerald-500/20 active:scale-[0.98] hover:bg-emerald-400 transition-all text-lg"
                >
                  حفظ وتفعيل الاتصال الحقيقي
                </button>
             </div>
          </section>
        )}
      </main>

      {/* Mobile Nav */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-[#080808]/95 backdrop-blur-2xl border-t border-white/10 p-4 flex justify-around items-center z-50">
