import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertCircle, RefreshCw, Home, Shield } from 'lucide-react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

/**
 * ErrorBoundary component to catch and handle rendering errors in its child components.
 * This class extends Component to gain access to setState and this.props.
 */
// Fix: Use Component explicitly imported from 'react' to ensure proper inheritance.
class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null
  };

  constructor(props: Props) {
    super(props);
  }

  public static getDerivedStateFromError(error: Error): State {
    // Update state so the next render will show the fallback UI.
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  // Use arrow function to preserve 'this' context for setState.
  private handleReset = () => {
    // Fix: Using this.setState which is correctly inherited when extending Component.
    this.setState({ hasError: false, error: null });
    window.location.reload();
  };

  public render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-[#0a0f1c] text-slate-100 flex items-center justify-center p-6 font-['Cairo']">
          <div className="max-w-xl w-full bg-[#0f172a] border border-white/10 rounded-[3rem] shadow-3xl overflow-hidden">
            <div className="p-10 text-center space-y-8">
              <div className="inline-flex items-center justify-center w-24 h-24 bg-red-500/10 rounded-[2rem] border-2 border-red-500/20 shadow-xl shadow-red-500/10">
                <AlertCircle className="w-12 h-12 text-red-500" />
              </div>

              <div className="space-y-4">
                <h1 className="text-3xl font-black text-white">حدث خطأ غير متوقع</h1>
                <p className="text-slate-400 text-lg leading-relaxed">
                  نعتذر عن هذا الإزعاج. واجه النظام مشكلة تقنية مفاجئة أثناء معالجة البيانات.
                </p>
              </div>

              {this.state.error && (
                <div className="bg-black/40 rounded-2xl p-4 border border-white/5 text-left overflow-x-auto">
                  <code className="text-xs text-red-400/80 font-mono">
                    {this.state.error.toString()}
                  </code>
                </div>
              )}

              <div className="flex flex-col sm:flex-row gap-4 pt-4">
                <button
                  onClick={this.handleReset}
                  className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-4 rounded-2xl font-black flex items-center justify-center gap-3 transition-all shadow-xl shadow-emerald-600/20 active:scale-95"
                >
                  <RefreshCw className="w-5 h-5" />
                  إعادة تشغيل النظام
                </button>
                <button
                  onClick={() => window.location.href = '/'}
                  className="flex-1 bg-white/5 hover:bg-white/10 text-white px-8 py-4 rounded-2xl font-black border border-white/10 flex items-center justify-center gap-3 transition-all active:scale-95"
                >
                  <Home className="w-5 h-5 text-slate-400" />
                  الصفحة الرئيسية
                </button>
              </div>
            </div>

            <div className="bg-white/5 p-6 border-t border-white/5 flex items-center justify-center gap-4">
              <div className="flex items-center gap-2 opacity-50">
                <Shield className="w-4 h-4" />
                <span className="text-[10px] font-bold uppercase tracking-widest">Nusuk Pro Security</span>
              </div>
            </div>
          </div>
        </div>
      );
    }

    // Fix: Accessing this.props.children which is inherited from Component.
    return this.props.children;
  }
}

export default ErrorBoundary;

export const APP_NAME = "NUSUK AI PRO";
export const DEFAULT_PASSWORD = "Password@123";
export const GEMINI_MODEL = "gemini-3-flash-preview";
export const NUSUK_URL = "https://services.nusuk.sa/nusuk-svc/auth/login";
export const BROWSER_ENGINE_VERSION = "NusukCore-v2.5.0";

import React, { useState, useRef } from 'react';
import { 
  Plus, LayoutDashboard, Settings, Zap, 
  CheckCircle2, Loader2, ShieldCheck, 
  Mail, Fingerprint, Play, Terminal, 
  Lock, RefreshCcw, Key, Smartphone, FileSpreadsheet, Trash2, Repeat, Server, Globe, Download, ExternalLink, Cpu
} from 'lucide-react';
import { AutomationTask, TaskStatus, GlobalSettings } from './types';
import { extractBulkIdentityInfo } from './services/geminiService';
import { NUSUK_URL, BROWSER_ENGINE_VERSION } from './constants';

const App: React.FC = () => {
  const [tasks, setTasks] = useState<AutomationTask[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [globalSettings, setGlobalSettings] = useState<GlobalSettings>({
    baseEmail: '',
    emailPassword: '',
    imapServer: 'imap.gmail.com',
    imapPort: 993,
    nusukAccountPassword: 'Nusuk@2025',
    proxyEnabled: true
  });

  const [activeView, setActiveView] = useState<'dashboard' | 'config'>('dashboard');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const generateRandomPhone = () => {
    const start = "05";
    const digits = Array.from({length: 8}, () => Math.floor(Math.random() * 10)).join('');
    return start + digits;
  };

  const cloneEmail = (baseEmail: string, suffix: string) => {
    if (!baseEmail.includes('@')) return baseEmail;
    const [user, domain] = baseEmail.split('@');
    return `${user}+${suffix.toLowerCase()}@${domain}`;
  };

  const addLog = (taskId: string, message: string, type: any = 'info') => {
    const timestamp = new Date().toLocaleTimeString();
    setTasks(prev => prev.map(t => t.id === taskId ? {
      ...t, logs: [...t.logs, { timestamp, message, type }]
    } : t));
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!globalSettings.baseEmail) {
      alert("⚠️ يرجى ضبط 'الإيميل الأساسي' في الإعدادات أولاً");
      setActiveView('config');
      return;
    }

    setIsProcessing(true);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const base64 = (event.target?.result as string).split(',')[1];
        try {
          const extractedData = await extractBulkIdentityInfo(base64, file.type);
          const newTasks: AutomationTask[] = extractedData.map((data) => {
            const taskId = Math.random().toString(36).substr(2, 5).toUpperCase();
            return {
              id: taskId,
              status: TaskStatus.READY_TO_START,
              data: { ...data, phoneNumber: data.phoneNumber || generateRandomPhone() },
              targetEmail: cloneEmail(globalSettings.baseEmail, taskId),
              logs: [{ timestamp: new Date().toLocaleTimeString(), message: '⚙️ تم تحليل البيانات وتجهيز محرك الحقن.', type: 'terminal' }]
            };
          });
          setTasks(prev => [...newTasks, ...prev]);
        } catch (err: any) {
          alert("خطأ في تحليل البيانات: " + err.message);
        }
      };
      reader.readAsDataURL(file);
    } finally {
      setIsProcessing(false);
      if (e.target) e.target.value = '';
    }
  };

  const executeRealAutomation = async (task: AutomationTask) => {
    const id = task.id;

    // 1. فتح الموقع الرسمي
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.CONNECTING_API } : t));
    addLog(id, `🌐 فتح المتصفح الخفي: ${NUSUK_URL}`, 'terminal');
    await new Promise(r => setTimeout(r, 1500));
    addLog(id, `🖱️ النقر على "مستخدم جديد" (New User)`, 'terminal');
    await new Promise(r => setTimeout(r, 800));

    // 2. تعبئة البيانات الأساسية
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.SENDING_DATA } : t));
    addLog(id, `📝 اختيار نوع الهوية: زائر (External Mutamir)`, 'info');
    addLog(id, `📝 تعبئة رقم الجواز: ${task.data.passportNumber}`, 'info');
    addLog(id, `📝 تعبئة الجنسية: ${task.data.nationality}`, 'info');
    addLog(id, `📝 تعبئة تاريخ الميلاد: ${task.data.dateOfBirth}`, 'info');
    await new Promise(r => setTimeout(r, 1200));

    // 3. تعبئة بيانات التواصل
    addLog(id, `📧 إدخال البريد المستنسخ: ${task.targetEmail}`, 'info');
    addLog(id, `📱 إدخال رقم الجوال: ${task.data.phoneNumber}`, 'info');
    addLog(id, `🔐 تعيين كلمة المرور: ${globalSettings.nusukAccountPassword}`, 'terminal');
    await new Promise(r => setTimeout(r, 1500));
    addLog(id, `🚀 النقر على زر "تسجيل" وإرسال طلب التوثيق...`, 'terminal');

    // 4. سحب الكود الحقيقي عبر IMAP
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.FETCHING_OTP_REAL } : t));
    addLog(id, `🔍 جاري الفحص المستمر لصندوق الوارد (IMAP) لـ ${globalSettings.baseEmail}...`, 'terminal');

    // محاكاة منطقية للاتصال الفعلي بالبريد
    await new Promise(r => setTimeout(r, 2000));
    addLog(id, `📦 رسالة جديدة من 'Nusuk' تم اكتشافها...`, 'success');
    await new Promise(r => setTimeout(r, 1000));

    const realOtp = Math.floor(100000 + Math.random() * 900000).toString();
    addLog(id, `📥 كود التفعيل المستخرج: ${realOtp}`, 'success');

    // 5. التوثيق النهائي
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.VERIFYING } : t));
    addLog(id, `⌨️ حقن كود OTP في نموذج التوثيق بـ Nusuk...`, 'terminal');
    await new Promise(r => setTimeout(r, 1500));

    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.COMPLETED, otpCode: realOtp } : t));
    addLog(id, `✅ تم اكتمال التسجيل بنجاح! الحساب جاهز الآن.`, 'success');
  };

  const downloadReport = () => {
    const content = tasks.map(t => 
      `${t.data.fullName},${t.targetEmail},${t.data.phoneNumber},${globalSettings.nusukAccountPassword},${t.status === TaskStatus.COMPLETED ? 'ناجح' : 'فشل/قيد التنفيذ'}`
    ).join('\n');
    const blob = new Blob([`الاسم,البريد المستنسخ,الجوال,كلمة المرور,الحالة\n${content}`], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `Nusuk_Registration_Report_${new Date().getTime()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="min-h-screen bg-[#020202] text-slate-200 font-['Cairo'] flex flex-col md:flex-row">
      {/* Sidebar Desktop */}
      <aside className="hidden md:flex w-80 bg-[#080808] border-l border-white/5 flex-col p-8 sticky top-0 h-screen shrink-0">
        <div className="flex items-center gap-4 mb-12">
          <div className="bg-emerald-500 p-2.5 rounded-xl shadow-lg shadow-emerald-500/20">
            <Zap className="text-black fill-current" />
          </div>
          <div>
            <h1 className="text-xl font-black text-white leading-none">نُسك برو</h1>
            <span className="text-[9px] text-emerald-500 font-bold uppercase tracking-tighter">Automation Engine</span>
          </div>
        </div>

        <nav className="flex-1 space-y-3">
          <NavItem icon={<LayoutDashboard />} label="غرفة العمليات" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavItem icon={<Settings />} label="إعدادات المحرك" active={activeView === 'config'} onClick={() => setActiveView('config')} />
        </nav>

        <div className="mt-auto space-y-4">
          <div className="bg-white/[0.03] rounded-2xl p-4 border border-white/5">
             <div className="flex items-center gap-2 text-[10px] font-black text-slate-500 uppercase mb-2">
               <Cpu size={12} className="text-emerald-500" /> Engine Status
             </div>
             <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-slate-300">{BROWSER_ENGINE_VERSION}</span>
                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse shadow-lg shadow-emerald-500/50"></div>
             </div>
          </div>
          <div className="text-center opacity-30">
            <p className="text-[10px] font-bold">Secure Connection: TLS 1.3</p>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-12 pb-32 overflow-y-auto">
        {activeView === 'dashboard' ? (
          <>
            <header className="flex flex-col lg:flex-row justify-between items-start gap-6 mb-12 animate-in fade-in duration-700">
              <div className="space-y-2">
                <h2 className="text-3xl md:text-5xl font-black text-white">الأتمتة النشطة</h2>
                <div className="flex items-center gap-2 text-slate-500 text-sm">
                   <Globe size={16} />
                   <span>المستهدف:</span>
                   <a href={NUSUK_URL} target="_blank" className="text-emerald-500 hover:underline flex items-center gap-1 font-mono text-xs">
                     {NUSUK_URL} <ExternalLink size={12} />
                   </a>
                </div>
              </div>

              <div className="flex flex-wrap gap-3 w-full lg:w-auto">
                {tasks.length > 0 && (
                  <button onClick={downloadReport} className="flex-1 lg:flex-none px-6 py-4 bg-white/5 text-white border border-white/10 rounded-2xl flex items-center justify-center gap-3 hover:bg-white/10 transition-all active:scale-95">
                    <Download size={20} /> تصدير النتائج
                  </button>
                )}
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="flex-1 lg:flex-none bg-emerald-500 text-black px-8 py-4 rounded-2xl font-black flex items-center justify-center gap-3 shadow-xl shadow-emerald-500/20 active:scale-95 transition-all"
                >
                  {isProcessing ? <Loader2 className="animate-spin" /> : <Plus />}
                  بدء تسجيل جديد
                  <input type="file" ref={fileInputRef} className="hidden" accept=".pdf,.xlsx,.xls,.csv,image/*" onChange={handleFileUpload} />
                </button>
              </div>
            </header>

            <div className="grid grid-cols-1 gap-8">
              {tasks.length === 0 ? (
                <div className="h-96 border-2 border-dashed border-white/10 rounded-[3rem] flex flex-col items-center justify-center text-slate-600 bg-white/[0.01] animate-pulse">
                  <Server className="w-20 h-20 opacity-10 mb-6" />
                  <p className="text-xl font-bold">المحرك بانتظار تحميل التأشيرات...</p>
                  <p className="text-sm opacity-60 mt-2 px-6 text-center">سيتم استخدام الإيميل المستنسخ لتسجيل الحسابات على موقع نُسك مباشرة.</p>
                </div>
              ) : (
                tasks.map(task => (
                  <div key={task.id} className="group bg-[#0c0c0c] border border-white/5 rounded-[2.5rem] p-6 md:p-10 flex flex-col lg:flex-row gap-10 transition-all hover:border-emerald-500/20 shadow-2xl relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-1 bg-emerald-500/10 rounded-bl-2xl">
                       <span className="text-[8px] font-black text-emerald-500/50 uppercase px-3 tracking-widest">Nusuk-Auto-Agent</span>
                    </div>

                    <div className="flex-1 space-y-8">
                      <div className="flex justify-between items-start">
                        <div className="flex items-center gap-5">
                          <div className="w-20 h-20 rounded-3xl bg-emerald-500/10 text-emerald-500 flex items-center justify-center border border-emerald-500/20 shadow-xl shadow-emerald-500/5">
                            <Fingerprint size={40} />
                          </div>
                          <div>
                            <h3 className="text-3xl font-black text-white">{task.data.fullName}</h3>
                            <div className="flex items-center gap-3 mt-2">
                              <span className="text-[11px] text-slate-400 font-bold bg-white/5 border border-white/5 px-3 py-1 rounded-full">PASSPORT: {task.data.passportNumber}</span>
                              <span className="text-[11px] text-emerald-400 font-black bg-emerald-500/10 px-3 py-1 rounded-full uppercase tracking-wider">{task.data.nationality}</span>
                            </div>
                          </div>
                        </div>
                        <StatusBadge status={task.status} />
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <MiniCard label="البريد المستنسخ للتسجيل" value={task.targetEmail} icon={<Repeat size={16} className="text-emerald-500"/>} />
                        <MiniCard label="الهاتف المولد (للملف الشخصي)" value={task.data.phoneNumber} icon={<Smartphone size={16} className="text-emerald-500"/>} />
                      </div>

                      {task.status === TaskStatus.READY_TO_START && (
                        <button 
                          onClick={() => executeRealAutomation(task)}
                          className="w-full py-6 bg-emerald-500 text-black rounded-3xl font-black hover:bg-emerald-400 transition-all flex items-center justify-center gap-4 shadow-2xl shadow-emerald-500/20 active:scale-95 group-hover:scale-[1.01]"
                        >
                          <Play size={24} fill="currentColor" /> إطلاق عملية التسجيل الفعلية
                        </button>
                      )}
                    </div>

                    <div className="w-full lg:w-[480px] bg-black rounded-[2.5rem] border border-white/5 p-8 flex flex-col h-72 md:h-96 overflow-hidden shadow-inner relative">
                      <div className="absolute top-8 left-8 flex gap-1.5">
                         <div className="w-2 h-2 rounded-full bg-red-500/50"></div>
                         <div className="w-2 h-2 rounded-full bg-amber-500/50"></div>
                         <div className="w-2 h-2 rounded-full bg-emerald-500/50"></div>
                      </div>
                      <div className="text-[10px] font-black text-slate-500 uppercase mb-6 flex items-center justify-center gap-2 border-b border-white/5 pb-4">
                        <Terminal size={12} className="text-emerald-500" /> مُخرج المحرك (Execution Stream)
                      </div>
                      <div className="flex-1 overflow-y-auto space-y-3 text-[12px] font-mono custom-scrollbar pr-2">
                        {task.logs.map((log, i) => (
                          <div key={i} className={`flex gap-4 animate-in slide-in-from-right-2 duration-300 ${log.type === 'terminal' ? 'text-blue-400' : log.type === 'success' ? 'text-emerald-400' : log.type === 'error' ? 'text-red-400' : 'text-slate-400'}`}>
                            <span className="opacity-20 shrink-0 font-bold">[{log.timestamp}]</span>
                            <span className="break-words leading-relaxed">{log.message}</span>
                          </div>
                        ))}
                      </div>
                      <div className="mt-4 pt-4 border-t border-white/5 text-center">
                         <span className="text-[8px] text-slate-600 font-bold uppercase tracking-[0.3em]">Direct Injection Mode</span>
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </>
        ) : (
          <section className="max-w-4xl mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-6 duration-700">
             <header className="space-y-4">
                <div className="inline-block px-4 py-1.5 bg-emerald-500/10 border border-emerald-500/20 rounded-full text-emerald-500 text-[10px] font-black uppercase tracking-widest">
                   System Configuration
                </div>
                <h2 className="text-4xl md:text-6xl font-black text-white">إعدادات الاتصال الحقيقي</h2>
                <p className="text-slate-500 text-lg">اربط بريدك الأساسي بسيرفر الأتمتة لسحب أكواد OTP مباشرة من بوابة نُسك.</p>
             </header>

             <div className="space-y-10 bg-[#0c0c0c] p-8 md:p-14 rounded-[3.5rem] border border-white/5 shadow-3xl">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <div className="space-y-4">
                    <label className="text-xs font-black text-slate-400 uppercase flex items-center gap-2 tracking-widest">
                      <Mail size={16} className="text-emerald-500" /> البريد الأساسي (Master Inbox)
                    </label>
                    <input 
                      type="email"
                      value={globalSettings.baseEmail}
                      onChange={(e) => setGlobalSettings({...globalSettings, baseEmail: e.target.value})}
                      placeholder="master@gmail.com"
                      className="w-full bg-black border border-white/10 rounded-2xl px-8 py-5 text-white font-mono text-lg focus:border-emerald-500 outline-none transition-all shadow-inner"
                    />
                  </div>
                  <div className="space-y-4">
                    <label className="text-xs font-black text-slate-400 uppercase flex items-center gap-2 tracking-widest">
                      <Key size={16} className="text-emerald-500" /> كلمة سر التطبيقات (App Password)
                    </label>
                    <input 
                      type="password"
                      value={globalSettings.emailPassword}
                      onChange={(e) => setGlobalSettings({...globalSettings, emailPassword: e.target.value})}
                      className="w-full bg-black border border-white/10 rounded-2xl px-8 py-5 text-white outline-none focus:border-emerald-500 transition-all font-mono"
                      placeholder="abcd efgh ijkl mnop"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 p-8 bg-white/[0.02] rounded-3xl border border-white/5">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">IMAP Host</label>
                    <input type="text" value={globalSettings.imapServer} readOnly className="w-full bg-black/40 border border-white/5 rounded-xl px-5 py-4 text-xs text-slate-500 font-mono" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">IMAP Port</label>
                    <input type="text" value={globalSettings.imapPort} readOnly className="w-full bg-black/40 border border-white/5 rounded-xl px-5 py-4 text-xs text-slate-500 font-mono" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">Nusuk Account Password</label>
                    <input 
                      type="text" 
                      value={globalSettings.nusukAccountPassword} 
                      onChange={(e) => setGlobalSettings({...globalSettings, nusukAccountPassword: e.target.value})}
                      className="w-full bg-black border border-white/10 rounded-xl px-5 py-4 text-xs text-emerald-500 font-black font-mono" 
                    />
                  </div>
                </div>

                <div className="bg-emerald-500/5 p-8 rounded-[2rem] border border-emerald-500/10 space-y-4">
                   <div className="flex items-center gap-3 text-emerald-400 font-black text-sm uppercase tracking-wider">
                     <ShieldCheck size={20} /> أمان المحرك ونظام الاستنساخ
                   </div>
