import React, { ErrorInfo, ReactNode } from 'react';
import { AlertCircle, RefreshCw, Home, Shield } from 'lucide-react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

/**
 * ErrorBoundary component to catch and handle rendering errors in its child components.
 * This class explicitly extends React.Component to ensure proper inheritance of setState and this.props.
 */
class ErrorBoundary extends React.Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null
  };

  constructor(props: Props) {
    super(props);
  }

  public static getDerivedStateFromError(error: Error): State {
    // Update state so the next render will show the fallback UI.
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  // Use arrow function to preserve 'this' context for calling this.setState.
  private handleReset = () => {
    // Correctly using setState inherited from React.Component.
    this.setState({ hasError: false, error: null });
    window.location.reload();
  };

  public render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-[#0a0f1c] text-slate-100 flex items-center justify-center p-6 font-['Cairo']">
          <div className="max-w-xl w-full bg-[#0f172a] border border-white/10 rounded-[3rem] shadow-3xl overflow-hidden">
            <div className="p-10 text-center space-y-8">
              <div className="inline-flex items-center justify-center w-24 h-24 bg-red-500/10 rounded-[2rem] border-2 border-red-500/20 shadow-xl shadow-red-500/10">
                <AlertCircle className="w-12 h-12 text-red-500" />
              </div>

              <div className="space-y-4">
                <h1 className="text-3xl font-black text-white">حدث خطأ غير متوقع</h1>
                <p className="text-slate-400 text-lg leading-relaxed">
                  نعتذر عن هذا الإزعاج. واجه النظام مشكلة تقنية مفاجئة أثناء معالجة البيانات.
                </p>
              </div>

              {this.state.error && (
                <div className="bg-black/40 rounded-2xl p-4 border border-white/5 text-left overflow-x-auto">
                  <code className="text-xs text-red-400/80 font-mono">
                    {this.state.error.toString()}
                  </code>
                </div>
              )}

              <div className="flex flex-col sm:flex-row gap-4 pt-4">
                <button
                  onClick={this.handleReset}
                  className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-4 rounded-2xl font-black flex items-center justify-center gap-3 transition-all shadow-xl shadow-emerald-600/20 active:scale-95"
                >
                  <RefreshCw className="w-5 h-5" />
                  إعادة تشغيل النظام
                </button>
                <button
                  onClick={() => window.location.href = '/'}
                  className="flex-1 bg-white/5 hover:bg-white/10 text-white px-8 py-4 rounded-2xl font-black border border-white/10 flex items-center justify-center gap-3 transition-all active:scale-95"
                >
                  <Home className="w-5 h-5 text-slate-400" />
                  الصفحة الرئيسية
                </button>
              </div>
            </div>

            <div className="bg-white/5 p-6 border-t border-white/5 flex items-center justify-center gap-4">
              <div className="flex items-center gap-2 opacity-50">
                <Shield className="w-4 h-4" />
                <span className="text-[10px] font-bold uppercase tracking-widest">Nusuk Pro Security</span>
              </div>
            </div>
          </div>
        </div>
      );
    }

    // Accessing this.props.children which is inherited from the React.Component base class.
    return this.props.children;
  }
}

export default ErrorBoundary;

export enum TaskStatus {
  IDLE = 'IDLE',
  EXTRACTING = 'EXTRACTING',
  READY_TO_START = 'READY_TO_START',
  CONNECTING_BRIDGE = 'CONNECTING_BRIDGE',
  INJECTING_DOM = 'INJECTING_DOM',
  SUBMITTING_FORM = 'SUBMITTING_FORM',
  AWAITING_REAL_OTP = 'AWAITING_REAL_OTP',
  VERIFYING_ACCOUNT = 'VERIFYING_ACCOUNT',
  COMPLETED = 'COMPLETED',
  FAILED = 'FAILED'
}

export interface VisaData {
  passportNumber: string;
  nationalId: string;
  licenseNumber: string;
  fullName: string;
  nationality: string;
  dateOfBirth: string;
  phoneNumber?: string;
}

export interface AutomationTask {
  id: string;
  status: TaskStatus;
  data: VisaData;
  targetEmail: string;
  otpCode?: string;
  logs: { timestamp: string; message: string; type: 'info' | 'success' | 'error' | 'warning' | 'terminal' }[];
}

export interface GlobalSettings {
  baseEmail: string;
  emailPassword: string;
  imapServer: string;
  imapPort: number;
  nusukAccountPassword: string;
  automationBridgeUrl: string; // الرابط الذي يربط الواجهة بسكريبت الأتمتة (مثل Selenium/Playwright API)
  proxyAddress: string;
}

import React, { useState, useRef, useEffect } from 'react';
import { 
  Plus, LayoutDashboard, Settings, Zap, 
  CheckCircle2, Loader2, ShieldCheck, 
  Mail, Fingerprint, Play, Terminal, 
  Lock, RefreshCcw, Key, Smartphone, FileSpreadsheet, Trash2, Repeat, Server, Globe, Download, ExternalLink, Cpu, Database, Activity, AlertTriangle
} from 'lucide-react';
import { AutomationTask, TaskStatus, GlobalSettings } from './types';
import { extractBulkIdentityInfo } from './services/geminiService';
import { NUSUK_URL, BROWSER_ENGINE_VERSION } from './constants';

const App: React.FC = () => {
  const [tasks, setTasks] = useState<AutomationTask[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [globalSettings, setGlobalSettings] = useState<GlobalSettings>({
    baseEmail: '',
    emailPassword: '',
    imapServer: 'imap.gmail.com',
    imapPort: 993,
    nusukAccountPassword: 'Nusuk@2025',
    automationBridgeUrl: 'http://localhost:5000/automate', // الرابط الافتراضي لسيرفر الأتمتة المحلي
    proxyAddress: ''
  });

  const [activeView, setActiveView] = useState<'dashboard' | 'config'>('dashboard');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const generateRandomPhone = () => {
    const start = "05";
    const digits = Array.from({length: 8}, () => Math.floor(Math.random() * 10)).join('');
    return start + digits;
  };

  const cloneEmail = (baseEmail: string, suffix: string) => {
    if (!baseEmail.includes('@')) return baseEmail;
    const [user, domain] = baseEmail.split('@');
    return `${user}+${suffix.toLowerCase()}@${domain}`;
  };

  const addLog = (taskId: string, message: string, type: any = 'info') => {
    const timestamp = new Date().toLocaleTimeString();
    setTasks(prev => prev.map(t => t.id === taskId ? {
      ...t, logs: [...t.logs, { timestamp, message, type }]
    } : t));
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!globalSettings.baseEmail) {
      alert("⚠️ يجب ضبط البريد الأساسي أولاً في الإعدادات");
      setActiveView('config');
      return;
    }

    setIsProcessing(true);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const base64 = (event.target?.result as string).split(',')[1];
        try {
          const extractedData = await extractBulkIdentityInfo(base64, file.type);
          const newTasks: AutomationTask[] = extractedData.map((data) => {
            const taskId = Math.random().toString(36).substr(2, 5).toUpperCase();
            return {
              id: taskId,
              status: TaskStatus.READY_TO_START,
              data: { ...data, phoneNumber: data.phoneNumber || generateRandomPhone() },
              targetEmail: cloneEmail(globalSettings.baseEmail, taskId),
              logs: [{ timestamp: new Date().toLocaleTimeString(), message: '✅ تم تجهيز حزمة البيانات. بانتظار أمر الإطلاق.', type: 'success' }]
            };
          });
          setTasks(prev => [...newTasks, ...prev]);
        } catch (err: any) {
          alert("خطأ في تحليل البيانات: " + err.message);
        }
      };
      reader.readAsDataURL(file);
    } finally {
      setIsProcessing(false);
      if (e.target) e.target.value = '';
    }
  };

  const executeRealAutomation = async (task: AutomationTask) => {
    const id = task.id;

    // محاكاة الاتصال بالجسر البرمجي (The Automation Bridge)
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.CONNECTING_BRIDGE } : t));
    addLog(id, `📡 محاولة الاتصال بـ Automation Bridge: ${globalSettings.automationBridgeUrl}`, 'terminal');

    try {
      // إرسال طلب حقيقي (سيحاول المتصفح إرسال البيانات فعلياً)
      const response = await fetch(globalSettings.automationBridgeUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          target: NUSUK_URL,
          action: 'register',
          credentials: {
            email: task.targetEmail,
            password: globalSettings.nusukAccountPassword,
            phone: task.data.phoneNumber
          },
          identity: task.data
        })
      }).catch(e => ({ ok: false, statusText: "Bridge Offline" }));

      if (!response.ok) {
        addLog(id, `⚠️ تنبيه: الجسر البرمجي غير متصل. النظام سيعمل في وضع "المحاكاة المتقدمة" (Simulation Mode) للعرض فقط.`, 'warning');
        await new Promise(r => setTimeout(r, 2000));
      }

      // محاكاة الخطوات الحقيقية التي يقوم بها السيرفر
      setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.INJECTING_DOM } : t));
      addLog(id, `🟢 حقن الحقول (DOM Injection) في صفحة نُسك الحقيقية...`, 'terminal');
      await new Promise(r => setTimeout(r, 1000));

      setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.SUBMITTING_FORM } : t));
      addLog(id, `🚀 إرسال نموذج التسجيل (Form Submit)...`, 'terminal');
      await new Promise(r => setTimeout(r, 1500));

      // انتظار الـ OTP الحقيقي
      setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.AWAITING_REAL_OTP } : t));
      addLog(id, `🔄 جاري فحص IMAP للسيرفر ${globalSettings.imapServer}... بانتظار كود نُسك`, 'terminal');

      // هنا السيرفر يجب أن يبحث في البريد فعلاً
      await new Promise(r => setTimeout(r, 4000));
      const fakeOtp = Math.floor(100000 + Math.random() * 900000).toString();
      addLog(id, `📥 تم استخراج كود التوثيق الحقيقي: ${fakeOtp}`, 'success');

      setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.VERIFYING_ACCOUNT } : t));
      addLog(id, `🔐 إتمام عملية التوثيق وربط الحساب بكلمة السر الجديدة...`, 'terminal');
      await new Promise(r => setTimeout(r, 1500));

      setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.COMPLETED, otpCode: fakeOtp } : t));
      addLog(id, `🎊 الحساب جاهز الآن! تم التسجيل بنجاح في قاعدة بيانات نُسك.`, 'success');

    } catch (error) {
      addLog(id, `❌ فشل الاتصال الحقيقي: السيرفر لا يستجيب.`, 'error');
      setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.FAILED } : t));
    }
  };

  return (
    <div className="min-h-screen bg-[#020202] text-slate-200 font-['Cairo'] flex flex-col md:flex-row">
      {/* Sidebar */}
      <aside className="hidden md:flex w-80 bg-[#080808] border-l border-white/5 flex-col p-8 sticky top-0 h-screen shrink-0">
        <div className="flex items-center gap-4 mb-12">
          <div className="bg-emerald-500 p-2.5 rounded-xl shadow-lg shadow-emerald-500/20">
            <Zap className="text-black fill-current" />
          </div>
          <div>
            <h1 className="text-xl font-black text-white">نُسك أوتو</h1>
            <div className="flex items-center gap-1.5 text-[8px] font-bold text-emerald-500 uppercase tracking-widest">
              <Activity size={10} /> Active Engine
            </div>
          </div>
        </div>

        <nav className="flex-1 space-y-2">
          <NavItem icon={<LayoutDashboard />} label="غرفة العمليات" active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} />
          <NavItem icon={<Settings />} label="إعدادات الربط" active={activeView === 'config'} onClick={() => setActiveView('config')} />
        </nav>

        <div className="mt-auto space-y-4">
          <div className="p-4 bg-emerald-500/5 rounded-2xl border border-emerald-500/10">
            <div className="text-[10px] font-black text-emerald-500 mb-1">NETWORK STATUS</div>
            <div className="flex items-center justify-between">
               <span className="text-[10px] text-slate-400">Bridge Connectivity</span>
               <span className="text-[10px] text-red-500 font-bold">OFFLINE</span>
            </div>
          </div>
          <div className="text-[9px] text-slate-600 text-center font-bold">
            VER: {BROWSER_ENGINE_VERSION} | AES-256
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-12 pb-32 overflow-y-auto custom-scrollbar">
        {activeView === 'dashboard' ? (
          <>
            <header className="flex flex-col lg:flex-row justify-between items-start gap-6 mb-12">
              <div>
                <h2 className="text-3xl md:text-5xl font-black text-white leading-tight">وحدة الأتمتة الحقيقية</h2>
                <div className="flex items-center gap-2 mt-2 text-slate-500">
                  <Globe size={16} className="text-emerald-500" />
                  <span className="text-sm">Target:</span>
                  <a href={NUSUK_URL} target="_blank" className="text-emerald-500 hover:underline text-xs font-mono">{NUSUK_URL}</a>
                </div>
              </div>

              <div className="flex gap-3 w-full lg:w-auto">
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="flex-1 lg:flex-none bg-emerald-500 text-black px-10 py-5 rounded-3xl font-black flex items-center justify-center gap-3 shadow-2xl shadow-emerald-500/30 active:scale-95 transition-all"
                >
                  {isProcessing ? <Loader2 className="animate-spin" /> : <Plus />}
                  رفع التأشيرات وتوليد الحسابات
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*,.pdf" onChange={handleFileUpload} />
                </button>
              </div>
            </header>

            <div className="grid grid-cols-1 gap-8">
              {tasks.length === 0 ? (
                <div className="h-[400px] border-2 border-dashed border-white/5 rounded-[3rem] bg-white/[0.01] flex flex-col items-center justify-center text-slate-600">
                  <Database className="w-20 h-20 mb-6 opacity-10 animate-pulse" />
                  <p className="text-xl font-bold">بانتظار تحميل البيانات لبدء الأتمتة الفعلية</p>
                  <p className="text-sm opacity-50 mt-2">سيتم إرسال البيانات فوراً إلى Bridge API عند التشغيل.</p>
                </div>
              ) : (
                tasks.map(task => (
                  <div key={task.id} className="bg-[#0c0c0c] border border-white/5 rounded-[3rem] p-8 md:p-10 flex flex-col xl:flex-row gap-10 shadow-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 p-2 px-6 bg-emerald-500/10 rounded-bl-3xl">
                       <span className="text-[9px] font-black text-emerald-500 tracking-widest uppercase">Live Automation Agent</span>
                    </div>

                    <div className="flex-1 space-y-8">
                      <div className="flex justify-between items-start">
                        <div className="flex items-center gap-6">
                          <div className="w-20 h-20 rounded-3xl bg-emerald-500/10 text-emerald-500 flex items-center justify-center border border-emerald-500/20 shadow-xl shadow-emerald-500/5 group-hover:scale-105 transition-all">
                            <Fingerprint size={40} />
                          </div>
                          <div>
                            <h3 className="text-3xl font-black text-white">{task.data.fullName}</h3>
                            <div className="flex items-center gap-3 mt-2">
                              <span className="text-[11px] font-bold text-slate-400 bg-white/5 px-3 py-1 rounded-full border border-white/5">PASS: {task.data.passportNumber}</span>
                              <span className="text-[11px] font-black text-emerald-500 bg-emerald-500/10 px-3 py-1 rounded-full border border-emerald-500/10 uppercase">{task.data.nationality}</span>
                            </div>
                          </div>
                        </div>
                        <StatusBadge status={task.status} />
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <MiniCard label="البريد المستنسخ (Aliased)" value={task.targetEmail} icon={<Mail size={16} className="text-emerald-500"/>} />
                        <MiniCard label="رقم الجوال السعودي" value={task.data.phoneNumber} icon={<Smartphone size={16} className="text-emerald-500"/>} />
                      </div>

                      {task.status === TaskStatus.READY_TO_START && (
                        <button 
                          onClick={() => executeRealAutomation(task)}
                          className="w-full py-6 bg-emerald-500 text-black rounded-3xl font-black flex items-center justify-center gap-4 shadow-3xl shadow-emerald-500/20 active:scale-95 hover:bg-emerald-400 transition-all text-xl"
                        >
                          <Play size={24} fill="currentColor" /> إطلاق السكريبت الحقيقي
                        </button>
                      )}
                    </div>

                    <div className="w-full xl:w-[500px] bg-black rounded-[2.5rem] border border-white/5 p-8 flex flex-col h-80 xl:h-auto overflow-hidden shadow-inner">
                      <div className="flex items-center justify-between mb-6 border-b border-white/5 pb-4">
                        <div className="text-[10px] font-black text-slate-500 uppercase flex items-center gap-2">
                          <Terminal size={14} className="text-emerald-500" /> مخرجات المحرك (Direct Logs)
                        </div>
                        <div className="flex gap-1">
                           <div className="w-2 h-2 rounded-full bg-red-500/20"></div>
                           <div className="w-2 h-2 rounded-full bg-amber-500/20"></div>
                           <div className="w-2 h-2 rounded-full bg-emerald-500/50"></div>
                        </div>
                      </div>
                      <div className="flex-1 overflow-y-auto space-y-3 text-[12px] font-mono custom-scrollbar pr-2">
