  const [globalSettings, setGlobalSettings] = useState<GlobalSettings>({
    baseEmail: '',
    emailPassword: '',
    imapServer: 'imap.gmail.com',
    imapPort: 993,
    nusukAccountPassword: 'Nusuk@2025',
    automationBridgeUrl: 'http://localhost:5000/automate',
    proxyAddress: ''
  });

  const [activeView, setActiveView] = useState<'dashboard' | 'config'>('dashboard');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const generateRandomPhone = () => {
    const start = "05";
    const digits = Array.from({length: 8}, () => Math.floor(Math.random() * 10)).join('');
    return start + digits;
  };

  const cloneEmail = (baseEmail: string, suffix: string) => {
    if (!baseEmail.includes('@')) return baseEmail;
    const [user, domain] = baseEmail.split('@');
    return `${user}+${suffix.toLowerCase()}@${domain}`;
  };

  const addLog = (taskId: string, message: string, type: any = 'info') => {
    const timestamp = new Date().toLocaleTimeString();
    setTasks(prev => prev.map(t => t.id === taskId ? {
      ...t, logs: [...t.logs, { timestamp, message, type }]
    } : t));
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!globalSettings.baseEmail) {
      alert("⚠️ يرجى ضبط الإعدادات أولاً");
      setActiveView('config');
      return;
    }

    setIsProcessing(true);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const base64 = (event.target?.result as string).split(',')[1];
        try {
          const extractedData = await extractBulkIdentityInfo(base64, file.type);
          const newTasks: AutomationTask[] = extractedData.map((data) => {
            const taskId = Math.random().toString(36).substr(2, 5).toUpperCase();
            return {
              id: taskId,
              status: TaskStatus.READY_TO_START,
              data: { ...data, phoneNumber: data.phoneNumber || generateRandomPhone() },
              targetEmail: cloneEmail(globalSettings.baseEmail, taskId),
              logs: [{ timestamp: new Date().toLocaleTimeString(), message: '📦 تم تجهيز البيانات للإرسال إلى Bridge.', type: 'info' }]
            };
          });
          setTasks(prev => [...newTasks, ...prev]);
        } catch (err: any) {
          alert("خطأ في تحليل البيانات: " + err.message);
        }
      };
      reader.readAsDataURL(file);
    } finally {
      setIsProcessing(false);
      if (e.target) e.target.value = '';
    }
  };

  const executeRealAutomation = async (task: AutomationTask) => {
    const id = task.id;
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.CONNECTING_BRIDGE } : t));
    addLog(id, `📡 إرسال الأوامر إلى Bridge API...`, 'terminal');

    try {
      const response = await fetch(globalSettings.automationBridgeUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          task_id: task.id,
          nusuk_url: NUSUK_URL,
          email: task.targetEmail,
          password: globalSettings.nusukAccountPassword,
          imap_config: {
            user: globalSettings.baseEmail,
            pass: globalSettings.emailPassword,
            server: globalSettings.imapServer
          },
          identity: task.data
        })
      });

      const result = await response.json();

      if (result.success) {
        addLog(id, `✅ تم استلام كود OTP من السكريبت: ${result.otp}`, 'success');
        setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.COMPLETED, otpCode: result.otp } : t));
      } else {
        throw new Error(result.error || "خطأ في السكريبت");
      }

    } catch (error: any) {
      addLog(id, `❌ فشل الاتصال بالبايثون: تأكد من تشغيل سكريبت Bridge.py`, 'error');
      setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.FAILED } : t));
    }
  };

