    const script = `
import locale
from flask import Flask, request, jsonify
from flask_cors import CORS
import time
import re
import imaplib
import email
from playwright.sync_api import sync_playwright

app = Flask(__name__)
CORS(app)

def get_otp_from_email(imap_user, imap_pass, imap_server):
    print(f"[*] Searching for OTP in {imap_user}...")
    for _ in range(30): # Try for 5 minutes
        try:
            mail = imaplib.IMAP4_SSL(imap_server)
            mail.login(imap_user, imap_pass)
            mail.select("inbox")
            status, messages = mail.search(None, '(FROM "nusuk" UNSEEN)')
            if status == "OK":
                for num in reversed(messages[0].split()):
                    status, data = mail.fetch(num, "(RFC822)")
                    msg = email.message_from_bytes(data[0][1])
                    content = str(msg.get_payload())
                    otp = re.search(r'\\b(\\d{6})\\b', content)
                    if otp:
                        return otp.group(1)
            mail.logout()
        except Exception as e:
            print(f"Error: {e}")
        time.sleep(10)
    return None

@app.route('/automate', methods=['POST'])
def automate():
    data = request.json
    try:
        with sync_playwright() as p:
            browser = p.chromium.launch(headless=False) # Change to True for background
            page = browser.new_page()
            page.goto(data['nusuk_url'])

            # الخطوات الفعلية في موقع نُسك (تحتاج ضبط محددات CSS الدقيقة)
            print("[+] Filling Nusuk Form...")
            # مثال: page.fill('input[name="passport"]', data['identity']['passportNumber'])

            # بعد الضغط على تسجيل، ننتظر الـ OTP
            otp = get_otp_from_email(
                data['imap_config']['user'], 
                data['imap_config']['pass'], 
                data['imap_config']['server']
            )

            if otp:
                # إدخال الكود في الموقع
                # page.fill('.otp-input', otp)
                # page.click('#confirm-btn')
                return jsonify({"success": True, "otp": otp})
            else:
                return jsonify({"success": false, "error": "Timeout waiting for OTP"})

    except Exception as e:
        return jsonify({"success": False, "error": str(e)})

if __name__ == '__main__':
    app.run(port=5000)
    `;
    const blob = new Blob([script], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
