              <div className="flex items-center justify-between">
                <h3 className="text-2xl font-black text-white flex items-center gap-3"><Code className="text-emerald-500"/> تحميل سكريبت الربط</h3>
                <button onClick={downloadPythonScript} className="bg-white/5 border border-white/10 px-6 py-3 rounded-2xl flex items-center gap-2 hover:bg-white/10 transition-all font-bold">
                  <Download size={18}/> تحميل Bridge.py
                </button>
              </div>

              <div className="space-y-4">
                <h4 className="text-emerald-500 font-bold uppercase tracking-widest text-xs">خطوات التشغيل (بايثون):</h4>
                <div className="bg-black p-6 rounded-2xl border border-white/5 text-sm font-mono text-slate-400 space-y-2">
                  <p>1. <span className="text-white">pip install flask flask-cors playwright</span></p>
                  <p>2. <span className="text-white">playwright install chromium</span></p>
                  <p>3. شغل السكريبت: <span className="text-emerald-500">python bridge.py</span></p>
                </div>
              </div>

