    />
  </div>
);

const NavItem = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl transition-all ${active ? 'bg-emerald-500 text-black font-black' : 'text-slate-500 hover:text-white'}`}>
    {icon} <span>{label}</span>
  </button>
);

const MiniCard = ({ label, value, icon }: any) => (
  <div className="bg-white/5 p-4 rounded-2xl border border-white/5">
    <div className="flex items-center gap-2 opacity-40 text-[9px] font-black uppercase mb-1">{icon} {label}</div>
    <div className="text-sm font-bold truncate">{value || '---'}</div>
  </div>
);

const StatusBadge = ({ status }: any) => {
  const map: any = {
    [TaskStatus.READY_TO_START]: { l: 'جاهز', c: 'text-emerald-400 bg-emerald-500/10' },
    [TaskStatus.CONNECTING_BRIDGE]: { l: 'جاري الإرسال...', c: 'text-blue-400 bg-blue-500/10 animate-pulse' },
    [TaskStatus.COMPLETED]: { l: 'مكتمل ✅', c: 'text-emerald-500 bg-emerald-500/20' },
    [TaskStatus.FAILED]: { l: 'خطأ في الربط', c: 'text-red-400 bg-red-500/10' },
  };
  const s = map[status] || { l: 'تحليل...', c: 'text-slate-500' };
  return <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase ${s.c}`}>{s.l}</div>;
};

export default App;

