import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertCircle, RefreshCw, Home, Shield } from 'lucide-react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

/**
 * ErrorBoundary component to catch and handle rendering errors in its child components.
 * This class explicitly extends React.Component to ensure proper inheritance of setState and props.
 */
// Explicitly extending React.Component with typed Props and State to resolve inheritance visibility in TypeScript
class ErrorBoundary extends React.Component<Props, State> {
  public state: State = {
    hasError: false,
    error: null
  };

  constructor(props: Props) {
    super(props);
  }

  public static getDerivedStateFromError(error: Error): State {
    // Update state so the next render will show the fallback UI.
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  // Use arrow function to preserve 'this' context, ensuring it correctly refers to the React.Component instance for setState.
  private handleReset = () => {
    // Accessing the inherited setState method from React.Component
    this.setState({ hasError: false, error: null });
    window.location.reload();
  };

  public render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-[#0a0f1c] text-slate-100 flex items-center justify-center p-6 font-['Cairo']">
          <div className="max-w-xl w-full bg-[#0f172a] border border-white/10 rounded-[3rem] shadow-3xl overflow-hidden">
            <div className="p-10 text-center space-y-8">
              <div className="inline-flex items-center justify-center w-24 h-24 bg-red-500/10 rounded-[2rem] border-2 border-red-500/20 shadow-xl shadow-red-500/10">
                <AlertCircle className="w-12 h-12 text-red-500" />
              </div>

              <div className="space-y-4">
                <h1 className="text-3xl font-black text-white">حدث خطأ غير متوقع</h1>
                <p className="text-slate-400 text-lg leading-relaxed">
                  نعتذر عن هذا الإزعاج. واجه النظام مشكلة تقنية مفاجئة أثناء معالجة البيانات.
                </p>
              </div>

              {this.state.error && (
                <div className="bg-black/40 rounded-2xl p-4 border border-white/5 text-left overflow-x-auto">
                  <code className="text-xs text-red-400/80 font-mono">
                    {this.state.error.toString()}
                  </code>
                </div>
              )}

              <div className="flex flex-col sm:flex-row gap-4 pt-4">
                <button
                  onClick={this.handleReset}
                  className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-4 rounded-2xl font-black flex items-center justify-center gap-3 transition-all shadow-xl shadow-emerald-600/20 active:scale-95"
                >
                  <RefreshCw className="w-5 h-5" />
                  إعادة تشغيل النظام
                </button>
                <button
                  onClick={() => window.location.href = '/'}
                  className="flex-1 bg-white/5 hover:bg-white/10 text-white px-8 py-4 rounded-2xl font-black border border-white/10 flex items-center justify-center gap-3 transition-all active:scale-95"
                >
                  <Home className="w-5 h-5 text-slate-400" />
                  الصفحة الرئيسية
                </button>
              </div>
            </div>

            <div className="bg-white/5 p-6 border-t border-white/5 flex items-center justify-center gap-4">
              <div className="flex items-center gap-2 opacity-50">
                <Shield className="w-4 h-4" />
                <span className="text-[10px] font-bold uppercase tracking-widest">Nusuk Pro Security</span>
              </div>
            </div>
          </div>
        </div>
      );
    }

    // Accessing the inherited props from React.Component to resolve TypeScript error
    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { useState, useRef, useEffect } from 'react';
import { 
  Plus, LayoutDashboard, Settings, Zap, 
  CheckCircle2, Loader2, ShieldCheck, 
  Mail, Fingerprint, Play, Terminal, 
  Lock, RefreshCcw, Key, Smartphone, FileSpreadsheet, Trash2, Repeat, Server, Globe, Download, ExternalLink, Cpu, Database, Activity, AlertTriangle, Code, Copy, Info
} from 'lucide-react';
import { AutomationTask, TaskStatus, GlobalSettings } from './types';
import { extractBulkIdentityInfo } from './services/geminiService';
import { NUSUK_URL, BROWSER_ENGINE_VERSION } from './constants';

const App: React.FC = () => {
  const [tasks, setTasks] = useState<AutomationTask[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [globalSettings, setGlobalSettings] = useState<GlobalSettings>({
    baseEmail: '',
    emailPassword: '',
    imapServer: 'imap.gmail.com',
    imapPort: 993,
    nusukAccountPassword: 'Nusuk@2025',
    automationBridgeUrl: 'http://localhost:5000/automate',
    proxyAddress: ''
  });

  const [activeView, setActiveView] = useState<'dashboard' | 'config'>('dashboard');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const generateRandomPhone = () => {
    const start = "05";
    const digits = Array.from({length: 8}, () => Math.floor(Math.random() * 10)).join('');
    return start + digits;
  };

  const cloneEmail = (baseEmail: string, suffix: string) => {
    if (!baseEmail.includes('@')) return baseEmail;
    const [user, domain] = baseEmail.split('@');
    return `${user}+${suffix.toLowerCase()}@${domain}`;
  };

  const addLog = (taskId: string, message: string, type: any = 'info') => {
    const timestamp = new Date().toLocaleTimeString();
    setTasks(prev => prev.map(t => t.id === taskId ? {
      ...t, logs: [...t.logs, { timestamp, message, type }]
    } : t));
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!globalSettings.baseEmail) {
      alert("⚠️ يرجى ضبط الإعدادات أولاً");
      setActiveView('config');
      return;
    }

    setIsProcessing(true);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const base64 = (event.target?.result as string).split(',')[1];
        try {
          const extractedData = await extractBulkIdentityInfo(base64, file.type);
          const newTasks: AutomationTask[] = extractedData.map((data) => {
            const taskId = Math.random().toString(36).substr(2, 5).toUpperCase();
            return {
              id: taskId,
              status: TaskStatus.READY_TO_START,
              data: { ...data, phoneNumber: data.phoneNumber || generateRandomPhone() },
              targetEmail: cloneEmail(globalSettings.baseEmail, taskId),
              logs: [{ timestamp: new Date().toLocaleTimeString(), message: '📦 تم تجهيز البيانات للإرسال إلى Bridge.', type: 'info' }]
            };
          });
          setTasks(prev => [...newTasks, ...prev]);
        } catch (err: any) {
          alert("خطأ في تحليل البيانات: " + err.message);
        }
      };
      reader.readAsDataURL(file);
    } finally {
      setIsProcessing(false);
      if (e.target) e.target.value = '';
    }
  };

  const executeRealAutomation = async (task: AutomationTask) => {
    const id = task.id;
    setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.CONNECTING_BRIDGE } : t));
    addLog(id, `📡 إرسال الأوامر إلى Bridge API (المنفذ 5000)...`, 'terminal');

    try {
      const response = await fetch(globalSettings.automationBridgeUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          task_id: task.id,
          nusuk_url: NUSUK_URL,
          email: task.targetEmail,
          password: globalSettings.nusukAccountPassword,
          imap_config: {
            user: globalSettings.baseEmail,
            pass: globalSettings.emailPassword,
            server: globalSettings.imapServer
          },
          identity: task.data
        })
      });

      const result = await response.json();

      if (result.success) {
        addLog(id, `✅ تم استلام كود OTP من السكريبت: ${result.otp}`, 'success');
        setTasks(prev => prev.map(t => t.id === id ? { ...t, status: TaskStatus.COMPLETED, otpCode: result.otp } : t));
      } else {
        throw new Error(result.error || "خطأ في السكريبت");
