    apkDownloadUrl: '',
    proxyAddress: ''
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsExtracting(true);
    try {
      const reader = new FileReader();
      reader.onload = async () => {
        const base64 = (reader.result as string).split(',')[1];
        const extractedData = await extractBulkIdentityInfo(base64, file.type);

        const newTasks: AutomationTask[] = extractedData.map(data => ({
          id: `NSK-${Math.random().toString(36).substr(2, 5).toUpperCase()}`,
          status: TaskStatus.READY_TO_START,
          data: data,
          targetEmail: `${data.passportNumber.toLowerCase()}@temp.com`,
          logs: [{ timestamp: new Date().toLocaleTimeString(), message: 'تم استخراج بيانات التأشيرة بنجاح', type: 'success' }]
        }));

        setTasks(prev => [...newTasks, ...prev]);
        setIsExtracting(false);
      };
      reader.readAsDataURL(file);
    } catch (error) {
      console.error(error);
      setIsExtracting(false);
    }
  };

  const startNusukAutomation = async (taskId: string) => {
    const task = tasks.find(t => t.id === taskId);
    if (!task) return;

    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: TaskStatus.CONNECTING_BRIDGE } : t));

    try {
      const response = await fetch(globalSettings.mobileBridgeUrl + '/nusuk_register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          visa_data: task.data,
          email: task.targetEmail,
          password: globalSettings.nusukAccountPassword
        })
      });

      const result = await response.json();
      if (result.success) {
        setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: TaskStatus.COMPLETED } : t));
      } else {
        throw new Error(result.error);
      }
    } catch (error: any) {
      setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: TaskStatus.FAILED, logs: [...t.logs, {timestamp: '', message: error.message, type: 'error'}] } : t));
