import os
import time
from flask import Flask, request, jsonify
from flask_cors import CORS

app = Flask(__name__)
CORS(app)

def run_adb(command):
    return os.popen(f"adb {command}").read()

@app.route('/android/nusuk_register', methods=['POST'])
