        # 2. الضغط على "مستخدم جديد" (مثال لإحداثيات)
        run_adb("shell input tap 500 1800") 
        time.sleep(2)

        # 3. ملء البيانات (رقم التأشيرة، الجواز، إلخ)
        # سيقوم السكريبت بإرسال الأوامر بناءً على الحقول
        run_adb(f"shell input text {visa['passportNumber']}")

        return jsonify({"success": True, "message": "Automation started on device"})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)})

if __name__ == '__main__':
    app.run(port=5001, host='0.0.0.0')
    `;
    const blob = new Blob([script], { type: 'text/plain' });
