import { GoogleGenAI, Type } from "@google/genai";
import { GEMINI_MODEL } from "../constants";
import { VisaData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const extractBulkIdentityInfo = async (base64Data: string, mimeType: string): Promise<VisaData[]> => {
  try {
    const response = await ai.models.generateContent({
      model: GEMINI_MODEL,
      contents: {
        parts: [
          { inlineData: { mimeType, data: base64Data } },
          { text: "Extract ALL pilgrims/visa data from this document. For each person I need: Full Name (Arabic/English), Passport Number, Visa Number (if available), Nationality, and Date of Birth. Return strictly as a JSON array of objects." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              passportNumber: { type: Type.STRING },
              visaNumber: { type: Type.STRING },
              fullName: { type: Type.STRING },
              nationality: { type: Type.STRING },
              dateOfBirth: { type: Type.STRING }
            },
            required: ["fullName", "passportNumber", "nationality"]
          }
        }
      }
    });

    const text = response.text || "[]";
    return JSON.parse(text);
  } catch (error) {
    console.error("Bulk AI Extraction Failed:", error);
    throw new Error("فشل استخراج بيانات ملف التأشيرات المجمع");
  }
};

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertCircle, RefreshCw, Home, Shield } from 'lucide-react';

interface Props {
  children?: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

/**
 * ErrorBoundary component to catch and handle rendering errors in its child components.
 */
// Fix: Directly extending Component from 'react' helps resolve visibility issues for state, setState, and props in some TypeScript environments.
class ErrorBoundary extends Component<Props, State> {
  // Explicitly define state and props types to ensure they are correctly inherited and recognized.
  public state: State = {
    hasError: false,
    error: null
  };

  constructor(props: Props) {
    super(props);
    // Initializing state in constructor.
    this.state = {
      hasError: false,
      error: null
    };
  }

  // static method required by React to update state when an error occurs during rendering.
  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  // Arrow function used to bind 'this' automatically for use in event handlers.
  private handleReset = () => {
    // setState is inherited from the base Component class.
    this.setState({ hasError: false, error: null });
    window.location.reload();
  };

  public render() {
    // Access state inherited from Component.
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-[#0a0f1c] text-slate-100 flex items-center justify-center p-6 font-['Cairo']">
          <div className="max-w-xl w-full bg-[#0f172a] border border-white/10 rounded-[3rem] shadow-3xl overflow-hidden">
            <div className="p-10 text-center space-y-8">
              <div className="inline-flex items-center justify-center w-24 h-24 bg-red-500/10 rounded-[2rem] border-2 border-red-500/20 shadow-xl shadow-red-500/10">
                <AlertCircle className="w-12 h-12 text-red-500" />
              </div>

              <div className="space-y-4">
                <h1 className="text-3xl font-black text-white">حدث خطأ غير متوقع</h1>
                <p className="text-slate-400 text-lg leading-relaxed">
                  نعتذر عن هذا الإزعاج. واجه النظام مشكلة تقنية مفاجئة أثناء معالجة البيانات.
                </p>
              </div>

              {this.state.error && (
                <div className="bg-black/40 rounded-2xl p-4 border border-white/5 text-left overflow-x-auto">
                  <code className="text-xs text-red-400/80 font-mono">
                    {this.state.error.toString()}
                  </code>
                </div>
              )}

              <div className="flex flex-col sm:flex-row gap-4 pt-4">
                <button
                  onClick={this.handleReset}
                  className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-4 rounded-2xl font-black flex items-center justify-center gap-3 transition-all shadow-xl shadow-emerald-600/20 active:scale-95"
                >
                  <RefreshCw className="w-5 h-5" />
                  إعادة تشغيل النظام
                </button>
                <button
                  onClick={() => window.location.href = '/'}
                  className="flex-1 bg-white/5 hover:bg-white/10 text-white px-8 py-4 rounded-2xl font-black border border-white/10 flex items-center justify-center gap-3 transition-all active:scale-95"
                >
                  <Home className="w-5 h-5 text-slate-400" />
                  الصفحة الرئيسية
                </button>
              </div>
            </div>

            <div className="bg-white/5 p-6 border-t border-white/5 flex items-center justify-center gap-4">
              <div className="flex items-center gap-2 opacity-50">
                <Shield className="w-4 h-4" />
                <span className="text-[10px] font-bold uppercase tracking-widest">Nusuk Pro Security</span>
              </div>
            </div>
          </div>
        </div>
      );
    }

    // Access props inherited from Component.
    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { useState, useRef, useEffect } from 'react';
import { 
  Plus, LayoutDashboard, Settings, Zap, 
  Loader2, Mail, Fingerprint, Play, Terminal, 
  Download, Code, Copy, Info, Smartphone, Trash2, ShieldCheck, AlertTriangle, AppWindow, FileText, Upload, CheckCircle2, UserPlus, Wifi, WifiOff, RefreshCw
