const App: React.FC = () => {
  const [tasks, setTasks] = useState<AutomationTask[]>([]);
  const [isExtracting, setIsExtracting] = useState(false);
  const [activeView, setActiveView] = useState<'dashboard' | 'config'>('dashboard');
  const [bridgeStatus, setBridgeStatus] = useState<'online' | 'offline'>('offline');
  const [globalSettings, setGlobalSettings] = useState<GlobalSettings>({
    baseEmail: '',
    emailPassword: '',
    imapServer: 'imap.gmail.com',
    imapPort: 993,
    nusukAccountPassword: 'Nusuk@2025Auto',
    automationBridgeUrl: 'http://localhost:5000/automate',
    mobileBridgeUrl: 'http://localhost:5001/android',
    apkDownloadUrl: '',
    proxyAddress: ''
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Heartbeat to check bridge connection
  useEffect(() => {
    const checkBridge = async () => {
      try {
        const res = await fetch(globalSettings.mobileBridgeUrl + '/ping');
        if (res.ok) setBridgeStatus('online');
        else setBridgeStatus('offline');
      } catch {
        setBridgeStatus('offline');
      }
    };
    const timer = setInterval(checkBridge, 5000);
    checkBridge();
    return () => clearInterval(timer);
  }, [globalSettings.mobileBridgeUrl]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsExtracting(true);
    try {
      const reader = new FileReader();
      reader.onload = async () => {
        const base64 = (reader.result as string).split(',')[1];
        const extractedData = await extractBulkIdentityInfo(base64, file.type);

        const newTasks: AutomationTask[] = extractedData.map(data => ({
          id: `NSK-${Math.random().toString(36).substr(2, 5).toUpperCase()}`,
          status: TaskStatus.READY_TO_START,
          data: data,
          targetEmail: `${data.passportNumber.toLowerCase()}@temp.com`,
          logs: [{ timestamp: new Date().toLocaleTimeString(), message: 'تم استخراج بيانات التأشيرة بنجاح من الملف المجمع', type: 'success' }]
        }));

        setTasks(prev => [...newTasks, ...prev]);
        setIsExtracting(false);
      };
      reader.readAsDataURL(file);
    } catch (error) {
      console.error(error);
      setIsExtracting(false);
    }
  };

  const startNusukAutomation = async (taskId: string) => {
    if (bridgeStatus === 'offline') {
      alert("❌ سكريبت البايثون (Bridge) غير مفعل! يرجى تشغيله أولاً.");
      return;
    }

    const task = tasks.find(t => t.id === taskId);
    if (!task) return;

    setTasks(prev => prev.map(t => t.id === taskId ? { 
      ...t, 
      status: TaskStatus.CONNECTING_BRIDGE,
      logs: [...t.logs, { timestamp: new Date().toLocaleTimeString(), message: 'جاري محاولة الاتصال بالمحاكي عبر ADB...', type: 'info' }]
    } : t));

    try {
      const response = await fetch(globalSettings.mobileBridgeUrl + '/nusuk_register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          visa_data: task.data,
          email: task.targetEmail,
          password: globalSettings.nusukAccountPassword
        })
      });

      const result = await response.json();
      if (result.success) {
        setTasks(prev => prev.map(t => t.id === taskId ? { 
          ...t, 
          status: TaskStatus.COMPLETED,
          logs: [...t.logs, { timestamp: new Date().toLocaleTimeString(), message: '✅ اكتملت العملية بنجاح! راجع تطبيق نسك.', type: 'success' }]
        } : t));
      } else {
        throw new Error(result.error || "خطأ غير معروف في الجسر");
      }
    } catch (error: any) {
      setTasks(prev => prev.map(t => t.id === taskId ? { 
        ...t, 
        status: TaskStatus.FAILED, 
        logs: [...t.logs, { timestamp: new Date().toLocaleTimeString(), message: `❌ فشل: ${error.message}`, type: 'error' }] 
