    const script = `
import os
import time
import subprocess
from flask import Flask, request, jsonify
from flask_cors import CORS

app = Flask(__name__)
CORS(app)

def run_adb(command):
    try:
        result = subprocess.run(f"adb {command}", shell=True, capture_output=True, text=True)
        return result.stdout.strip()
    except Exception as e:
        return str(e)

@app.route('/android/ping', methods=['GET'])
def ping():
    # التحقق من وجود أجهزة متصلة
    devices = run_adb("devices")
    has_device = "device" in devices.split('\\n')[1] if len(devices.split('\\n')) > 1 else False
    return jsonify({
