  error: Error | null;
}

/**
 * ErrorBoundary component to catch and handle rendering errors in its child components.
 */
// Fix: Explicitly extending React.Component ensures that inherited members like props and setState are correctly recognized.
class ErrorBoundary extends React.Component<Props, State> {
  constructor(props: Props) {
    super(props);
    // Initializing state in constructor is the standard way to ensure state is correctly setup in React Class Components.
    this.state = {
      hasError: false,
      error: null
    };
  }

  // static method required by React to update state when an error occurs during rendering.
  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  // Arrow function used to bind 'this' automatically for use in event handlers.
  private handleReset = () => {
    // setState is inherited from the base React.Component class.
    this.setState({ hasError: false, error: null });
    window.location.reload();
  };

  public render() {
    // Access state inherited from React.Component.
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-[#0a0f1c] text-slate-100 flex items-center justify-center p-6 font-['Cairo']">
          <div className="max-w-xl w-full bg-[#0f172a] border border-white/10 rounded-[3rem] shadow-3xl overflow-hidden">
