import { GoogleGenAI, Type } from "@google/genai";
import { GEMINI_MODEL } from "../constants";
import { VisaData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const extractBulkIdentityInfo = async (base64Data: string, mimeType: string): Promise<VisaData[]> => {
  try {
    const response = await ai.models.generateContent({
      model: GEMINI_MODEL,
      contents: {
        parts: [
          { inlineData: { mimeType, data: base64Data } },
          { text: "Extract ALL pilgrims/visa data. I need: fullName, passportNumber, visaNumber, nationality, dateOfBirth. Return as JSON array." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              passportNumber: { type: Type.STRING },
              visaNumber: { type: Type.STRING },
              fullName: { type: Type.STRING },
              nationality: { type: Type.STRING },
              dateOfBirth: { type: Type.STRING }
            },
            required: ["fullName", "passportNumber"]
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    throw new Error("فشل استخراج بيانات التأشيرات");
  }
};

export const analyzeAndModifyBarcode = async (barcodeBase64: string, visa: VisaData): Promise<any> => {
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const dateStr = tomorrow.toISOString().split('T')[0];
  const timeStr = "16:00 (04:00 PM)";

  try {
    const response = await ai.models.generateContent({
      model: GEMINI_MODEL,
      contents: {
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: barcodeBase64 } },
          { text: `This is a Nusuk permit. I want to generate a MODIFIED version for a new pilgrim. 
          Replace the original data with these:
          - New Name: ${visa.fullName}
          - New Passport: ${visa.passportNumber}
          - New Visa: ${visa.visaNumber || 'N/A'}
          - New DOB: ${visa.dateOfBirth}
          - New Reservation Date: ${dateStr}
          - New Reservation Time: ${timeStr}

          Return a JSON object representing the final permit details.` }
        ]
      },
      config: {
        responseMimeType: "application/json"
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (error) {
    throw new Error("فشل تحليل وتعديل الباركود");
  }
};

